(window.TZ_CONTENT=window.TZ_CONTENT||{})["sd"]={"taaruf.001": "تحريڪ جو تعارف", "taaruf.002": "هي هڪ غير سياسي ۽ فرقيواريت کان پاڪ اصلاحي تحريڪ آهي، جيڪا امامِ رباني مجدد الفِ ثانيؒ ۽ پنهنجي مرشدينِ ڪاملين، شمس الکونین خواجہ محمد عبدالخالق نقشبندی، قادری، سہروردیؒ، شمس العارفین حضرت سائیں عبدالرزاق خالقی نقشبندیؒ ۽ امام الذاکرین سائیں محمد عظیم اللہ رزاقی نقشبندیؒ جي طريقي تي ماڻهن کي شريعت ۽ سنت ڏانهن سڏي ٿي.", "taaruf.003": "هتي نه لالچ آهي، نه شهرت ۽ گهڻائي جو شوق، رڳو الله جي رضا ۽ دل ۽ نفس جي اصلاح آهي.", "taaruf.004": "تحريڪ جا مقصد", "taaruf.005": "تحريڪ اتباع سنت پاڪستان هڪ غير سياسي ۽ فرقيواريت کان پاڪ اسلامي تحريڪ آهي، جنهن ۾ امتِ مسلمه جو هر فرد رڪنيت حاصل ڪري سگهي ٿو. هن تحريڪ جا بنيادي مقصد هيٺ ڏجن ٿا:", "taaruf.006": "اڄ جي هن فتني ڀريل دور ۾، جڏهن بدعتون ۽ خرافات پنهنجي عروج تي آهن، امتِ مسلمه ۾ خدا جو خوف ۽ مصطفیٰ ﷺ جو عشق حاصل ڪرڻ لاءِ بدعتن ۽ خرافات کان بچڻ، ۽ شريعتِ مطهره ۽ سنتِ مصطفیٰ ﷺ کي سکڻ، سيکارڻ ۽ انهن تي عمل ڪرڻ جو شوق پيدا ڪرڻ. ان سلسلي ۾ وڌ کان وڌ درس و تدريس جو بندوبست ڪرڻ سان گڏوگڏ هلندي ڦرندي شريعت ۽ سنت جي تبليغ ڪرڻ.", "taaruf.007": "شريعت، سنت ۽ قرآن جي تعليم کي وڌائڻ لاءِ وڌ کان وڌ ديني مدرسا قائم ڪرڻ.", "taaruf.008": "خدمتِ خلق جو جذبو پيدا ڪرڻ ۽ يتيمن جي پرورش کي وڌائڻ لاءِ يتيم خانا قائم ڪرڻ.", "taaruf.009": "خاص ڪري نوجوان نسل کي بي حيائي ۽ برائي کان بچائي پنجن وقتن جي نماز باجماعت لاءِ مسجد ۾ آڻڻ.", "taaruf.010": "روزمره کان علاوه شادي وهانءَ ۽ ٻين خوشي ۽ غميءَ جي موقعن تي ٿيندڙ بدعتن کي ختم ڪرڻ ۽ شريعت ۽ سنت کي وڌائڻ لاءِ وڌ کان وڌ ذڪرِ خدا ۽ ذڪرِ مصطفیٰ ﷺ جون محفلون منعقد ڪرڻ.", "taaruf.011": "قرآن ۽ سنت جي روشنيءَ ۾ اولياءِ ڪاملين جي حقيقي تعليمات کي وڌائڻ، ۽ جعلي، شعبده باز ۽ پيڙهيءَ در پيڙهيءَ وارن پيرن جي گهڙيل تعليمات جو خاتمو ڪري، هن دور ۾ تصوف جي بگڙيل چهري کي تازگي بخشڻ.", "taaruf.012": "ڪريم آقا ﷺ سان ڪامل محبت حاصل ڪرڻ لاءِ درود و سلام ۽ ذڪر ۽ نعت جي محفلن کي وڌائڻ.", "taaruf.013": "سماجي ۽ اخلاقي براين جو خاتمو ڪرڻ ۽ سٺي سلوڪ ۽ اخلاقي تعليمات کي رواج ڏيڻ.", "taaruf.014": "عورتن ۾ فيشن پرستيءَ بدران شرعي پردي ۽ پنهنجن مڙسن جي تابعداريءَ جو رجحان پيدا ڪرڻ.", "taaruf.015": "سڄي عالمِ اسلام، خاص ڪري پياري وطن پاڪستان سان محبت ۽ وفاداريءَ جو جذبو پيدا ڪرڻ.", "taaruf.016": "اول وقت ۾ نماز ادا ڪرڻ کي وڌائڻ. اڄڪلهه فجر ۽ ظهر جون نمازون مسجدن ۾ گهڻي دير سان ادا ڪيون وڃن ٿيون، جيڪا نماز کان غفلت آهي، حالانڪ حنفي وقتن موجب وقت تمام اڳ ٿي ويندو آهي.", "taaruf.017": "ناموسِ رسالت ۽ ختمِ نبوت جو تحفظ ڪرڻ، ۽ يهود و هنود ۽ قاديانين جي سازشن کي بي نقاب ڪرڻ.", "taaruf.018": "اتباعِ رسول ﷺ", "taaruf.019": "قرآنِ ڪريم جي روشنيءَ ۾", "taaruf.020": "سورهٔ آلِ عمران ۾ الله تعاليٰ فرمائي ٿو: <span class=\"kk-ar\" style=\"display:block\">قُلْ اِنْ كُنْتُمْ تُحِبُّوْنَ اللّٰهَ فَاتَّبِعُوْنِيْ يُحْبِبْكُمُ اللّٰهُ وَيَغْفِرْ لَكُمْ ذُنُوْبَكُمْ</span>(فرمائي ڏيو! جيڪڏهن توهان الله سان محبت ڪريو ٿا ته منهنجي اتباع ڪريو، الله توهان سان محبت ڪندو ۽ توهان جا سڀ گناهه معاف فرمائيندو). آپ ﷺ خدا تعاليٰ جا محبوب آهن، ۽ محب ان ماڻهوءَ کي به پنهنجو محبوب بڻائي ڇڏيندو آهي جنهن ۾ پنهنجي محبوب جون عادتون ۽ خصلتون ڏسندو آهي. تنهنڪري آپ ﷺ جي تابعداريءَ ۾ ڪوشش ڪرڻ مقامِ محبوبيت تائين پهچائيندڙ ۽ گناهن کي مٽائيندڙ آهي. هر سياڻي ۽ عقلمند تي واجب آهي ته ظاهر ۽ باطن ۾ آپ ﷺ جي ڪامل تابعداريءَ ۾ ڪوشش ڪري.", "taaruf.021": "سورة الاحزاب ۾ فرمايو: <span class=\"kk-ar\" style=\"display:block\">لَقَدْ كَانَ لَكُمْ فِيْ رَسُوْلِ اللّٰهِ اُسْوَةٌ حَسَنَةٌ لِّمَنْ كَانَ يَرْجُوا اللّٰهَ وَالْيَوْمَ الْاٰخِرَ وَذَكَرَ اللّٰهَ كَثِيْرًا</span>(بيشڪ توهان لاءِ رسول الله ﷺ بهترين نمونو آهن، ان لاءِ جيڪو الله ۽ آخرت جي ڏينهن جي اميد رکي ٿو ۽ الله جو ذڪر گهڻو ڪري ٿو). تنهنڪري جيڪو الله ڏانهن رجوع ڪري ۽ آخرت جي تياري ڪرڻ چاهي ۽ گهڻو ذڪرِ الاهي به ڪندڙ هجي، ته ان کي گهرجي ته زندگيءَ جي هر هر پهلوءَ ۾ نبي ڪريم ﷺ جي روشن طريقي جي پيروي ڪري.", "taaruf.022": "سورة النساء ۾ فرمايو: <span class=\"kk-ar\" style=\"display:block\">مَنْ يُّطِعِ الرَّسُوْلَ فَقَدْ اَطَاعَ اللّٰهَ</span>(جنهن رسول ﷺ جي اطاعت ڪئي، تنهن حق تعاليٰ جي اطاعت ڪئي). معلوم ٿيو ته الله تعاليٰ پنهنجي اطاعت کي پنهنجي حبيب ﷺ جي اطاعت ۾ لڪائي رکيو آهي. اطاعتِ رسول ئي اطاعتِ الاهي آهي ۽ ذڪرِ رسول ﷺ عين ذڪرِ خدا آهي. هاڻي جيڪو رسول الله ﷺ جي اطاعت کي الله تعاليٰ جي اطاعت کان جدا سمجهي، اهو قرآن جو منڪر آهي.", "taaruf.023": "<b>اطاعتِ رسول ﷺ الله جي مقرب ٻانهن جي رفاقت ۽ ساٿ جو ذريعو:</b> سورة النساء ۾ فرمانِ الاهي آهي: <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَالرَّسُوْلَ فَاُولٰٓئِكَ مَعَ الَّذِيْنَ اَنْعَمَ اللّٰهُ عَلَيْهِمْ مِّنَ النَّبِيّٖنَ وَالصِّدِّيْقِيْنَ وَالشُّهَدَآءِ وَالصّٰلِحِيْنَ ۚ وَحَسُنَ اُولٰٓئِكَ رَفِيْقًا</span>(جنهن الله ۽ ان جي رسول ﷺ جي اطاعت ڪئي، ته اهي ماڻهو انهن حضرتن سان گڏ هوندا جن تي الله تعاليٰ انعام فرمايو، يعني انبياء، صديقين، شهداء ۽ صالحين، ۽ اهي حضرت ڏاڍا سٺا ساٿي آهن).", "taaruf.024": "<b>رسول الله ﷺ جي اطاعت کان سواءِ عمل ضايع ٿي وڃن ٿا:</b> سورهٔ محمد ۾ ارشادِ الاهي آهي: <span class=\"kk-ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَلَا تُبْطِلُوْٓا اَعْمَالَكُمْ</span>(اي ايمان وارؤ! الله جي اطاعت ڪريو ۽ رسول ﷺ جي اطاعت ڪريو ۽ پنهنجا عمل ضايع نه ڪريو).", "taaruf.025": "<b>اطاعتِ رسول ﷺ رحمتِ خداوندي جو ذريعو:</b> سورهٔ آلِ عمران ۾ آهي: <span class=\"kk-ar\" style=\"display:block\">وَاَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ لَعَلَّكُمْ تُرْحَمُوْنَ</span>(الله ۽ ان جي رسول ﷺ جي اطاعت ڪريو ته جيئن توهان تي رحم ڪيو وڃي).", "taaruf.026": "<b>اطاعتِ رسول ﷺ ٻنهي جهانن جي ڪاميابيءَ جو سبب:</b> <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ فَقَدْ فَازَ فَوْزًا عَظِيْمًا</span>۽ جنهن الله ۽ ان جي رسول ﷺ جي اطاعت ڪئي، تنهن تمام وڏي ڪاميابي حاصل ڪئي. (سورة الاحزاب)", "taaruf.027": "سورة النور جي آيت ۵۱ ۾ ڪامياب مؤمنن جي صفت بيان فرمائي: (مسلمانن جي ڳالهه ته اها آهي ته جڏهن کين ڪنهن مقدمي ۾ الله ۽ ان جي رسول ﷺ ڏانهن سڏيو وڃي ٿو ته جيئن انهن جي وچ ۾ فيصلو فرمائي، ته اهي چون ٿا ته اسان ٻڌو ۽ مڃيو، ۽ اهي ئي ماڻهو ڪاميابي ماڻيندڙ آهن). ايندڙ آيت ۾ فرمايو: <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ وَيَخْشَ اللّٰهَ وَيَتَّقْهِ فَاُولٰٓئِكَ هُمُ الْفَآئِزُوْنَ</span>(۽ جنهن الله ۽ ان جي رسول ﷺ جي اطاعت ڪئي ۽ الله کان ڊنو ۽ تقويٰ اختيار ڪئي، سو اهي ئي ماڻهو ڪامياب ٿيندڙ آهن). هن آيت جي وضاحت ۾ حضرت عمرؓ فرمايو ته جيڪو شخص فرضن ۾ الله تعاليٰ جي اطاعت ۽ سنتن ۾ رسول الله ﷺ جي پيروي ڪري ٿو، ۽ گذريل غلطين سبب الله تعاليٰ کان ڊڄي ٿو، ۽ ايندڙ زندگيءَ ۾ الله جي نافرمانيءَ کان بچي ٿو، اهي ئي ماڻهو ڪامياب آهن، ۽ ڪامياب اهو شخص آهي جنهن کي جهنم جي باهه کان بچائي جنت ۾ داخل ڪيو ويو. (ضیاء القرآن)", "taaruf.028": "سورة الانفال ۾ فرمايو: اي ايمان وارؤ! الله ۽ رسول ﷺ جي سڏ تي حاضر ٿيو جڏهن رسول توهان کي ان شيءِ لاءِ سڏين جيڪا توهان کي زندگي بخشيندي. (۲۴). حضور ﷺ جو سڏڻ ئي الله تعاليٰ جو سڏڻ آهي.", "taaruf.029": "سورة الحشر ۾ فرمانِ الاهي آهي: ۽ جيڪو ڪجهه توهان کي رسول ﷺ عطا فرمائين اهو وٺو ۽ جنهن کان منع فرمائين ان کان باز رهو ۽ الله کان ڊڄو. (۷). هن آيتِ ڪريمه مان معلوم ٿيو ته آپ ﷺ جي اطاعت، يعني احڪامِ الاهي تي عمل ڪرڻ ۽ منڪرات کان رڪجڻ واجب آهي، ۽ الله ان کي سخت عذاب ڏيندو جيڪو آپ ﷺ جي نافرماني ڪري.", "taaruf.030": "احاديثِ مبارڪه جي روشنيءَ ۾", "taaruf.031": "<span class=\"kk-ar\" style=\"display:block\">خَيْرُ الْهُدٰى هُدٰى مُحَمَّدٍ ﷺ</span>سڀ کان بهترين رستو حضرت محمد ﷺ جو رستو آهي. (بخاري)", "taaruf.032": "فرمانِ مصطفیٰ ﷺ آهي ته جيڪو شخص منهنجي سنت کان منهن موڙي يا ڄاڻي واڻي ڇڏي ڏئي، اهو اسان مان ناهي ۽ نه ئي اهو قيامت جي ڏينهن شفاعت جو حقدار هوندو. ۽ جنهن منهنجي سنت سان محبت ڪئي تنهن مون سان محبت ڪئي، ۽ جنهن مون سان محبت ڪئي سو جنت ۾ مون سان گڏ هوندو. (ترمذي)", "taaruf.033": "منهنجي امت جو هر شخص جنت ۾ داخل ٿيندو سواءِ ان جي جنهن منهنجو انڪار ڪيو (اهو جنت ۾ نه ويندو). پڇڻ تي فرمايو: جنهن منهنجي نافرماني ڪئي تنهن منهنجو انڪار ڪيو. ان تي قرآن شاهد آهي: ان ڏينهن ظالم شخص پنهنجا هٿ چٻي چٻي چوندو ته هاءِ ڪاش! مون رسول الله ﷺ جي راهه اختيار ڪئي هجي ها، هاءِ افسوس! ڪاش مون فلاڻي کي دوست نه بڻايو هجي ها. (سورة الفرقان: ۲۷)", "taaruf.034": "حضور نبي ڪريم ﷺ دعا فرمائي ته منهنجي نائبن تي الله تعاليٰ جي رحمت هجي. ڪنهن عرض ڪيو ته آپ ﷺ جا نائب ڪير آهن؟ فرمايو: جيڪي منهنجي سنت سان محبت ڪن ٿا ۽ ان کي الله تعاليٰ جي ٻانهن کي سيکارين ٿا. (جامع بيان العلم و فضله)", "taaruf.035": "پنهنجي وصال کان اڳ ارشاد فرمايو: توهان ۾ ٻه شيون ڇڏي وڃان ٿو، جيستائين انهن ٻنهي تي مضبوطيءَ سان قائم رهندؤ گمراهه نه ٿيندؤ، هڪ ڪتاب الله ۽ ٻي سنتِ رسول الله ﷺ. (بخاري، ڪتاب الاحڪام)", "taaruf.036": "اڪابرين جي قولن جي روشنيءَ ۾", "taaruf.037": "<b>ثاني اثنين سيدنا صديقِ اڪبر رضی اللہ عنہ:</b> پهريون خليفو ٿيڻ کانپوءِ پنهنجي تاريخي خطبي ۾ فرمايائون ته جيستائين مان الله تعاليٰ ۽ ان جي رسول ﷺ جي اطاعت ڪريان، توهان منهنجي اطاعت ڪجو، ۽ جيڪڏهن مان انهن جي خلاف ڪريان ته منهنجو ساٿ ڇڏي ڏجو. آپؓ کي اتباعِ رسول ﷺ جو ڪمال شوق هو. ان جو اندازو ان گفتگوءَ مان لڳائي سگهجي ٿو جيڪا آپؓ جي وصالِ مبارڪ کان ڪجهه ڪلاڪ اڳ آپ رضی اللہ عنہ ۽ آپ جي پياري صاحبزادي ام المؤمنين سيده عائشه صديقهؓ جي وچ ۾ ٿي. فرمايائون: عائشهؓ! توهان رسولِ خدا ﷺ کي ڪيترن ڪپڙن ۾ دفن ڪيو هو؟ عرض ڪيائون ته ٽن اڇن ڪپڙن ۾، جن ۾ نه قميص هئي نه عمامو. فرمايائون: رسول الله ﷺ ڪهڙي ڏينهن وفات ڪئي؟ عرض ڪيائون: سومر جي ڏينهن. فرمايائون: اڄ ڪهڙو ڏينهن آهي؟ عرض ڪيائون: سومر. فرمايائون: مون کي اميد آهي ته منهنجي وفات هن وقت ۽ رات جي وچ ۾ ٿيندي. پوءِ الله جي فضل سان ائين ئي ٿيو ته الله رب العزت وصال جي وقت به آپ رضی اللہ عنہ کي اتباعِ رسول ﷺ جو شرف عطا فرمايو، ۽ سومر جي ڏينهن ٽيهٺ سالن جي عمرِ مبارڪ ۾ آپ رضی اللہ عنہ جو وصال ٿيو. فرمائيندا هئا ته جنهن ڪم تي رسول الله ﷺ عمل فرمائيندا هئا، مان ان کي ڪرڻ کان سواءِ نٿو ڇڏيان؛ جيڪڏهن مان حضور ﷺ جي حال مان ڪو ڪم ڇڏي ڏيان ته مون کي ڊپ آهي ته سنتِ رسول ﷺ کان منحرف ٿي ويندس.", "taaruf.038": "<b>سلطان العارفین حضرت بایزید بسطامیؒ:</b> آپ کي هڪ شخص بابت معلوم ٿيو ته اهو هميشه کان راتين جو قيام ڪندڙ ۽ ڏينهن جو روزيدار آهي. فرمايائون: ان پنهنجي اندر مجاهدي سان ملائڪن جون صفتون پيدا ڪري ورتيون آهن، پر اهو ڪو مقام ناهي ۽ نه ئي اها ولايت آهي، بلڪه ڪمالِ ولايت اهو آهي ته پنهنجي اندر صفاتِ محمدي ﷺ پيدا ڪري، يعني پنهنجي زندگيءَ جا سمورا وقت، پنهنجو قيام ۽ روزو ۽ ڳالهائڻ ۽ کائڻ سنتِ مصطفیٰ ﷺ موجب ڍاري ڇڏي. شريعت جو رستو پلِ صراط کان به وڌيڪ سنهو ۽ خطرناڪ آهي، تنهنڪري ڪنهن به حالت ۾ شريعت جي حدن کان ٻاهر قدم نه رکڻ گهرجي.", "taaruf.039": "<b>سید الطائفہ شیخ جنید بغدادیؒ:</b> فرمائين ٿا ته شريعت جي اتباع ته رڳو اهو ئي ڪري سگهي ٿو جنهن جي سڄي هٿ ۾ قرآن پاڪ هجي ۽ کاٻي هٿ ۾ سنتِ مصطفیٰ ﷺ. انهن ٻنهي ڏيئن جي روشنيءَ ۾ رستو طئي ڪري ته جيئن نه شبهي جي کڏن ۾ ڪري ۽ نه بدعت جي اونداهين ۾ ڦاسي.", "taaruf.040": "<b>غوثِ زماں شیخ ابوالقاسم گرگانیؒ:</b> فرمائين ٿا ته پاڻيءَ جي مٿاڇري تي هلڻ، هوا ۾ اڏامڻ ۽ غيب جون ڳالهيون معلوم ڪرڻ ۽ بيان ڪرڻ، انهن مان ڪنهن کي به ڪرامت نٿو چئي سگهجي، ڇو ته اهو سڀ ڪجهه شيطان جي مدد سان به ممڪن ٿي سگهي ٿو، بلڪه ڪيترائي ڪاهن آهن جيڪي غيب جون ڳالهيون بيان ڪري ڇڏين ٿا. بلڪه سڀ کان وڏي ڪرامت اها آهي ته ماڻهو سراپا امرِ الاهي بڻجي وڃي ۽ تن، من ۽ ڌن سان شريعت جو تابع ٿي وڃي، ۽ ان جي ڪنهن ڪم يا حرڪت ۾ شريعت جي حڪمن جي ڀڃڪڙيءَ جو شائبو به نظر نه اچي. جيڪڏهن حالت اها هجي ته اهو قابلِ اعتبار آهي. شريعت جي پيرويءَ ۾ جيڪڏهن تون شينهن تي سواري نه ڪري سگهين ته ڪو حرج ناهي، ڇو ته ڪاوڙ ۽ غضب جي ان ڪتي، يعني نفس کي، جيڪو تنهنجي سيني ۾ موجود آهي، مغلوب ڪرڻ ڪيترن ئي شينهن تي سواري ڪرڻ کان درجن ڀيرا افضل آهي. نفس جي مڪر ۽ فريب کان آگاهي حاصل ڪرڻ سڀ کان وڏي غيب داني آهي. حس ۽ خيال جي دائري کان ٻاهر نڪري وڃڻ پاڻيءَ تي هلڻ ۽ هوا ۾ اڏامڻ کان ڪجهه گهٽ ته ناهي. دنيا جي لالچ ۽ دنيوي مشغلن کان بي نياز ٿي اڳتي نڪري وڃڻ، ۽ هڪ مشتبه يعني شڪي درهم کي ٺڪرائي ڇڏڻ، وڏن وڏن ميدانن ۽ جهنگلن کي ٽپي وڃڻ ۽ هڪ ڏکي لنگهه واري گهاٽيءَ کي پار ڪرڻ کان گهٽ ته ناهي، جو حق تعاليٰ انهن رڪاوٽن کي پنهنجي ڪلامِ پاڪ ۾ گهاٽين جو نالو ڏنو آهي.", "taaruf.041": "<b>حضرت داتا گنج بخش ہجویریؒ:</b> روحاني ترقيءَ لاءِ شريعت جي اتباع کي لازمي قرار ڏيندي فرمائين ٿا ته شريعت ۾ پهريون رڪن ڪتاب آهي. جيئن خدا تعاليٰ فرمائي ٿو: قرآن پاڪ ۾ محڪم آيتون آهن جيڪي ڪتاب جو اصل آهن. (سورهٔ آلِ عمران: ۷). ٻيو رڪن سنتِ رسول ﷺ آهي جنهن جو ماخذ حديثون آهن. جيئن قرآن پاڪ ۾ آهي: ۽ جيڪو رسول الله ﷺ فرمايو آهي ان تي عمل ڪريو ۽ جنهن ڳالهه کان منع فرمايو آهي ان کان بچو. (سورة الحشر). ٽيون رڪن اجماعِ امت آهي، جو رسول الله ﷺ فرمايو: منهنجي امت گمراهيءَ تي گڏ نه ٿيندي، هميشه سوادِ اعظم کي اختيار ڪريو. ان مان تقليد جو جائز هجڻ به واضح ٿي ويو. ڪو به صوفي شريعت ۽ حقيقت ۾ فرق نٿو ڪري سگهي. صوفيانه تعليمات مڪمل طور شريعت جي حڪمن جي تابع آهن. تنهنڪري طريقت دراصل شريعت کي ئي پنهنجي زندگيءَ جي اونهاين ۾ ماڻڻ جو نالو آهي.", "taaruf.042": "<b>غوث الاعظم محی الدین شیخ عبدالقادر جیلانیؒ:</b> فرمايائون ته اونداهيءَ ۾ ڏيئو کڻي داخل ٿيءُ، ۽ اهو ڏيئو ڪتاب الله ۽ نبي ڪريم ﷺ جي سنتِ مبارڪه آهي. ڪتاب ۽ سنت جي حڪمن کان هرگز ٻاهر نه نڪر. جيڪڏهن تنهنجي دل ۾ ڪو وسوسو اچي، جهڙوڪ زنا، وياج ۽ فاسق و فاجر ماڻهن سان ميل جول وغيره، يا ڪو الهام پيدا ٿئي، ته ان کي ڪتاب ۽ سنت جي روشنيءَ ۾ ڏس؛ جيڪڏهن تون ڪتاب ۽ سنت ۾ ان جي حرمت لهين ته ان کي قبول نه ڪر ۽ ان کان الڳ ٿي وڃ، ۽ اهو يقين ڪري وٺ ته اهو شيطان مردود جي طرف کان آهي. ٻانهو شريعت جي حدن جي حفاظت سبب ان غلام وانگر ٿي ويندو آهي جنهن کي مالڪ سمورا ڪم سونپي ڇڏيندو آهي. (فتوح الغیب)", "taaruf.043": "<b>شیخ الشیوخ شیخ شہاب الدین عمر سہروردیؒ:</b> سلسلهٔ سهرورديه جا باني ۽ حضرت بہاؤالدین زکریاؒ جا مرشد، ڪتاب عوارف المعارف ۾ فرمائين ٿا ته رسولِ اڪرم ﷺ فرمايو: ان ذات جو قسم جنهن جي قبضي ۾ منهنجي جان آهي! الله تعاليٰ کي اهي ئي ماڻهو محبوب آهن جيڪي ان جي ٻانهن ۾ محبتِ الاهي جو جذبو جاڳائين ٿا ۽ کين الله جو محبوب بڻائڻ جي ڪوشش ڪن ٿا، بلڪه زمين تي هر شخص جي خير خواهيءَ لاءِ سرگرمِ عمل رهن ٿا. هن حديث ۾ مشائخِ ڪرام جون صفتون بيان ڪيون ويون آهن. شيخ الله ڏانهن دعوت ۾ پيغمبرن جي نيابت ڪندي پنهنجي مريد ۾ الله جي محبت اهڙيءَ طرح پيدا ڪري ٿو جو ان کي رسولِ اڪرم ﷺ جي اتباع ۽ پيرويءَ جي راهه تي لڳائي تزڪيهٔ نفس جي راهه تي هلائي ٿو. سو جيڪو صحيح طريقي سان رسولِ اڪرم ﷺ جي اتباع ڪري ٿو، الله به ان سان محبت ڪرڻ لڳي ٿو.", "taaruf.044": "<b>امام الطریقت خواجۂ خواجگان سید محمد بہاؤالدین نقشبندؒ:</b> اسان جي طريقي جو بنياد حديثن ۽ آثار جي پيرويءَ تي آهي، ۽ اسان جو مقصد اهو آهي ته اسان جو سلوڪ سنتِ رسول ﷺ جي اتباع تي هجي ۽ حق ۽ باطل ۾ تميز ٿيندي رهي. خدا جا خاص ٻانها اهي آهن جيڪي شريعتِ مطهره جي پيروي ڪن ۽ اهلِ سنت و الجماعت جي مذهب تي پنهنجي زندگي پوري ڪن. جيڪڏهن رياضت ۾ چيله ڏنگي ٿي تنهنجو بدن ڪمان وانگر ٿي وڃي ۽ رياضت ۾ به ڪامياب هجين، پر جيستائين پنهنجو لقمو ۽ لباس پاڪ نه ڪندين ۽ شريعتِ رسول ﷺ جي پيروي نه ڪندين، منزلِ مقصود تائين نه پهچندين. تنهنڪري سڀني ڪمن جو دارومدار ان تي ئي آهي. (انیس الطالبین)", "taaruf.045": "<b>امامِ ربانی محبوبِ سبحانی حضرت مجدد الف ثانیؒ:</b> فرمائين ٿا ته شريعت جا ٽي جز آهن: علم، عمل ۽ اخلاص. جيستائين اهي ٽيئي جز ثابت نه ٿين، شريعت حاصل نٿي ٿئي. ۽ جڏهن شريعت حاصل ٿي وئي ته ڄڻ حق تعاليٰ جي رضامندي حاصل ٿي وئي، جيئن ارشادِ الاهي آهي: (۽ الله تعاليٰ جي رضا سڀ کان وڌيڪ آهي). تنهنڪري اهڙو ڪو مقصد باقي ناهي جنهن کي حاصل ڪرڻ لاءِ شريعت کان سواءِ ڪنهن ٻي شيءِ جي ضرورت پوي. طريقت ۽ حقيقت، جن سان صوفيا ممتاز آهن، شريعت جي ٽئين جز اخلاص کي ڪامل ڪرڻ ۾ شريعت جون خادم آهن. سو انهن ٻنهي جي تڪميل جو مقصد شريعت جي تڪميل آهي، نه ڪي شريعت کان سواءِ ڪو ٻيو ڪم. زبان سان ڪوڙ نه ڳالهائڻ شريعت آهي، ۽ دل مان ڪوڙ جو خيال دور ڪرڻ، يعني سچائيءَ جي عادت بنا تڪليف ۽ بناوٽ جي حاصل ٿي وڃڻ، حقيقت يعني تصوف آهي. تنهنڪري تصوف شريعت کي ڪامل ڪندڙ آهي، نه ڪي ان جو مخالف. اهي علوم ۽ معارف جيڪي صوفين کي هن راهه ۾ حاصل ٿين ٿا، اهي اصل مقصد نه آهن، بلڪه وهم ۽ خيال آهن جن سان طريقت جي ٻارن جي تربيت ڪئي ويندي آهي. انهن سڀني کان گذري مقامِ رضا تائين پهچڻ گهرجي، ڇو ته اهو جذبي ۽ سلوڪ جو سڀ کان اعليٰ مقام آهي. بي سمجهه ماڻهو انهن تجلين ۽ مشاهدن کي اصل مقصد سمجهي شريعت جي ڪمالن کان محروم رهجي وڃن ٿا. ها، مقامِ اخلاص ۽ مرتبهٔ رضا تائين پهچڻ انهن احوال کي طئي ڪرڻ ۽ علوم ۽ معارف حاصل ڪرڻ تي منحصر آهي. سو اهي احوال ۽ معارف اصل مقصد حاصل ڪرڻ لاءِ سبب ۽ وسيلو آهن. شريعت احوال جي تابع ناهي، بلڪه باطني احوال شريعت جا تابع آهن، ڇو ته شريعت قطعي آهي ۽ وحيءَ سان ثابت آهي، جڏهن ته احوال گماني آهن جيڪي ڪشف ۽ الهام سان ثابت ٿين ٿا. سو جنهن گروهه کي حق تعاليٰ آپ ﷺ جي اتباع سبب نهايت النهايه تائين پهچايو آهي، اهو علم ۽ عمل ۾ وار جيترو به شريعت جو مخالف نٿو ٿئي. ۽ علومِ لدني جيڪي انهن تي وارد ٿين ٿا، اهي شريعت جي موافق آهن، بلڪه علومِ شرعيه جي تفصيل آهن. هر اهو ڪشف جيڪو ظاهرِ شريعت جي خلاف هجي، قابلِ قبول ناهي، ڇو ته اهو آپ ﷺ جي رستي کان هٽيل آهي. سورهٔ یٰسین ۾ فرمانِ الاهي آهي: (بيشڪ آپ ﷺ رسولن مان آهيو ۽ سڌي رستي تي آهيو). عجب آهي ته ڪي ناقص پنهنجي خيالي ڪشف کي معتبر سمجهن ٿا ۽ روشن شريعت جي مخالفت ۽ انڪار ۾ ڪوشش ڪن ٿا، حالانڪ حضرت موسیٰ علیہ السلام به پنهنجي ڪليميءَ ۽ خاص قرب جي باوجود جيڪڏهن دنيا ۾ هجن ها ته اهي به هن ئي شريعتِ مطهره جي پيروي ڪن ها.", "taaruf.046": "سورة البقره ۾ آهي: جيڪي ايمان وارا آهن انهن جي محبت الله لاءِ تمام سخت آهي. (۱۶۵). تنهنڪري شرعي حڪم بجا آڻڻ جي توفيق محبتِ الاهي جو نتيجو آهي، ۽ باطني جمعيت جو حاصل ٿيڻ ان ئي محبت جو ميوو آهي. جيڪڏهن سڄي جهان جيتريون اونداهيون ۽ ڪدورتون باطن ۾ وجهي ڇڏين پر هيءَ محبت قائم رکن، ته ڪو غم نه ڪرڻ گهرجي؛ ۽ جيڪڏهن سڀني جبلن جيترا انوار ۽ ڪيفيتون باطن ۾ وڌائي ڇڏين پر هن محبت ۾ وار جيتري ڪمي ڪري ڇڏين، ته ان کي خرابيءَ کان سواءِ ٻيو ڪجهه نه سمجهڻ گهرجي. سچي ۽ ڪوڙي جي وچ ۾ فرق شريعت تي استقامت يا عدمِ استقامت مان معلوم ٿئي ٿو. جيڪو شخص سچو آهي، اهو سُڪر، مستي ۽ بيخوديءَ جي باوجود وار جيترو به شرع جي خلاف نٿو ڪري. مولانا رومؒ استغراق ۾ رهندا هئا پر نماز جي وقت هوش ۾ اچي ويندا هئا.", "taaruf.047": "رسول الله ﷺ فرمايو: توهان مان ڪو به مؤمن نه ٿيندو جيستائين ان جي خواهش ان امر جي تابع نه ٿي وڃي جيڪو مان کڻي آيو آهيان. تنهنڪري شرعي تڪليفن ۾ حڪمت اها ئي آهي ته نفسِ اماره خراب ۽ عاجز ٿئي. جيترو شريعت موجب عمل ڪبو، اوترو ئي نفساني خواهشون گهٽجي وينديون. اهو ئي سبب آهي ته شرعي حڪمن مان هڪ حڪم بجا آڻڻ نفساني خواهشن کي دور ڪرڻ ۾ انهن هزار سالن جي رياضتن ۽ مجاهدن کان، جيڪي پنهنجي طرفان ڪيا وڃن، ڪيترائي درجا بهتر آهي؛ بلڪه اهڙيون رياضتون ۽ مجاهدا جيڪي شرع موجب نه هجن، اهي نفساني خواهشن کي مدد ۽ طاقت ڏيندڙ آهن. برهمڻن ۽ جوگين کي محنت ۽ مجاهدن مان نفس جي تقويت ۽ تربيت کان سواءِ ڪو فائدو نه ٿيو. مثال طور فجر جي نماز جون ٻه رڪعتون جماعت سان ادا ڪرڻ، جيڪا سنتن مان هڪ سنت آهي، سڄي رات قيام ڪري فجر جي نماز بنا جماعت ادا ڪرڻ کان ڪيترائي درجا بهتر آهي؛ ۽ شريعت جي حڪم سان عيد الفطر جي ڏينهن کاڌو کائڻ پنهنجي مرضيءَ موجب ڪيترائي سال روزا رکڻ کان بهتر آهي؛ ۽ نفس کي خراب ڪرڻ لاءِ زڪوٰة طور هڪ رپيو خرچ ڪرڻ پنهنجي مرضيءَ سان هزار رپيا خرچ ڪرڻ کان بهتر آهي. مختصر ته جيستائين نفس صاف ٿي سرداريءَ جي پليديءَ کان پاڪ نه ٿئي، تيستائين نجات ڏکي آهي ۽ هميشه جي موت تائين پهچڻ جو خطرو آهي.", "taaruf.048": "پسنديده پيرويءَ جو هڪ ذرو سڀني دنيوي لذتن ۽ آخرت جي نعمتن کان ڪيترائي درجا بهتر آهي. بزرگي سنت جي تابعداريءَ تي، ۽ واڌارو شريعت جي بجا آوريءَ تي منحصر آهي. جيڪو ڪجهه شريعت جي مخالف آهي، مردود آهي. جنهن حقيقت کي شريعت رد ڪري ڇڏيو، اها زنديقي آهي. شريعت کي پنهنجي جاءِ تي قائم رکي حقيقت جي طلب ڪرڻ بهادرن جو ڪم آهي. حضور ﷺ جي دين جي حقيقت جي تصديق ڪرڻ کانپوءِ ٿورو عمل بجا آڻڻ به گهڻي عمل برابر آهي. اصحابِ ڪهف ايڏو وڏو درجو رڳو هڪ ئي نيڪيءَ سبب حاصل ڪيو، ۽ اها هئي نورِ ايماني سان گڏ خدا تعاليٰ جي دشمنن جي غلبي وقت هجرت ڪري وڃڻ؛ ڇو ته دشمنن جي غلبي وقت جيڪڏهن ٿوري به ڪوشش ڪن ته اها ايتري نمايان ۽ قابلِ اعتبار ٿيندي آهي جو امن جي ڏينهن ۾ ان کان ڪيترائي ڀيرا وڌيڪ عمل به اعتبار ۾ نٿو اچي سگهي. جيڪڏهن ظاهري هجرت ميسر نه ٿي سگهي ته باطني هجرت کي نظر ۾ رکندي مخلوق جي وچ ۾ رهندي به انهن کان الڳ رهڻ گهرجي. قيامت جي ڏينهن شريعت بابت پڇيو ويندو، نه ڪي تصوف بابت. جنت ۾ داخل ٿيڻ ۽ دوزخ کان بچڻ شريعت جا حڪم بجا آڻڻ تي منحصر آهي. انبياء ڪرام جي پيدائش جو مقصد شريعت جا حڪم ماڻهن تائين پهچائڻ ئي آهي. تنهنڪري سڀ کان وڏي ڳري نيڪي اها ئي آهي ته شرع کي رواج ڏيڻ ۽ ان جي حڪمن مان ڪنهن حڪم کي زنده ڪرڻ ۾ ڪوشش ڪئي وڃي، خاص ڪري اهڙي زماني ۾ جڏهن اسلام جا نشان بلڪل مٽجي ويا هجن. ۽ جنهن شخص سان گهڻن ماڻهن جي نجات وابسته هجي، اهو ان شخص کان بهتر آهي جيڪو رڳو پنهنجي نجات جي خيال ۾ آهي.", "taaruf.049": "ارشادِ الاهي آهي: (بيشڪ هيءَ منهنجي سڌي راهه آهي، توهان ان تي هلو ۽ ٻين رستن تي نه هلو). رسول الله ﷺ فرمايو: مون کي منهنجي رب ادب سيکاريو ۽ منهنجي تعليم ۽ تربيت سٺيءَ طرح ڪئي. تنهنڪري جيڪڏهن طريقت ۽ حقيقت جي راهه تي هلندڙن کان رستي دوران اهڙا ڪم سرزد ٿين جيڪي ظاهري طرح شريعت جي خلاف هجن، ته اهي غلبهٔ حال يعني مستيءَ تي ٻڌل آهن، ۽ هن مقام کان گذري هوش ۾ اچڻ تي اها مخالفت ختم ٿي ويندي آهي. محمدي المشرب بزرگ شرع ۽ سنت جي دولت سان مشرف آهن ۽ ولايتِ خاصهٔ محمدي ﷺ سندن حصو آهي. فناءِ اتم ۽ بقاءِ اڪمل انهن جي ئي شان آهي. ۽ ان جو مخالف، جيتوڻيڪ اولياء مان هجي ۽ ان کي ڪشف ٿيندو هجي، تڏهن به ان جو هن ولايت ۾ حصو ناهي، ۽ اهو گذريل پيغمبرن مان ڪنهن پيغمبر جي قدم تي آهي ۽ ان جا علوم ان ئي نبيءَ جي شريعت موافق آهن. شريعتِ محمدي ﷺ ٻين شريعتن جو خلاصو آهي. شريعت ۽ سنت جي اتباع کان سواءِ هن منزل تائين پهچڻ محال آهي. تنهنڪري ان شخص کي مبارڪ هجي جنهن کي هن ڳري نعمت جو شرف حاصل ٿيو، ۽ افسوس آهي ان شخص تي جيڪو هن اعليٰ نعمت کان محروم رهيو.", "taaruf.050": "آپ ﷺ جي ظاهري ميراث جو شڪر اهو آهي ته باطني ميراث سان آراسته ٿجي، ۽ باطني ميراث سان آراسته ٿيڻ آپ ﷺ جي ڪامل پيرويءَ کان سواءِ ناممڪن آهي. ۽ آپ ﷺ سان ڪمال محبت جي نشاني اها آهي ته حضور ﷺ جي دشمنن سان بغض رکجي ۽ شريعت جي مخالفن سان دشمنيءَ جو اظهار ڪجي. محبت ۾ خوشامد جائز ناهي، ڇو ته محب پنهنجي محبوب جو ديوانو هوندو آهي ۽ ٻه مخالف محبتون گڏ نٿيون ٿي سگهن. تنهنڪري لازم آهي ته پنهنجي سموري همت شرعي حڪمن جي بجا آوريءَ، اهلِ شريعت علماء ۽ اولياء جي تعظيم بجا آڻڻ ۽ بدعتين کي خوار رکڻ ۾ خرچ ڪجي. جنهن ڪنهن بدعتيءَ جي تعظيم ڪئي، ڄڻ اسلام کي ڪيرائڻ ۾ ان جي مدد ڪئي. حق تعاليٰ پنهنجي نبي ﷺ جي طفيل اسان جي ظاهر ۽ باطن کي سنتِ رسول ﷺ جي پيرويءَ سان آراسته ۽ پيراسته ڪري. (مکتوباتِ امامِ ربانی مجدد الف ثانیؒ)", "taaruf.051": "اسان جون گذارشون", "taaruf.052": "وطن سان محبت جو جذبو", "taaruf.053": "وطن سان محبت هڪ فطري ۽ سٺي ڳالهه آهي.", "taaruf.054": "تنهنڪري اسان کي گهرجي ته دينِ اسلام جي سربلنديءَ ۽ پنهنجي پياري وطن پاڪستان جي استحڪام لاءِ ڏينهن رات ڪوشش ڪندا رهون. ان سان گڏ پنهنجي ٻارن جي دلين ۾ خدا جي خوف ۽ مصطفیٰ ﷺ جي عشق سان گڏوگڏ وطن سان محبت جو جذبو به پيدا ڪريون. ان جو بهترين طريقو اهو آهي ته جشنِ آزاديءَ جي موقعي تي به الله تعاليٰ ۽ نبي ڪريم ﷺ جي ذڪر سان گڏ پنهنجي اسلاف جون سيرتون به بيان ڪيون وڃن. ان سان گڏ جيڪو شخص جنهن به کاتي ۾ پنهنجا فرض انجام ڏئي ٿو، اهو سچائي ۽ ايمانداريءَ کي پنهنجو شعار بڻائي، ايستائين جو گهر ۾ رهندڙ عورتون ۽ مرد به پنهنجون ذميواريون بهترين نموني انجام ڏين. پنهنجي سماج کي بهتر بڻائڻ لاءِ پنهنجي پاڙيسرين ۽ ويجهن مسڪينن ۽ فقيرن جو خيال رکو، ۽ پاڻ ۾ پيار محبت، اتفاق، اتحاد ۽ سٺي سلوڪ سان زندگي گذاريو. هڪ سٺو مسلمان ئي سٺو انسان ۽ هڪ سٺو پاڪستاني ٿي سگهي ٿو.", "taaruf.055": "بي پردگي ۽ موبائل فونن جو منفي استعمال ۽ انهن جي روڪٿام", "taaruf.056": "سورة النور ۾ فرمانِ الاهي آهي: ۽ آپ (ﷺ) مسلمان عورتن کي فرمائي ڏيو ته اهي پنهنجون نگاهون هيٺ رکن ۽ پنهنجي عفت جي حفاظت ڪن ۽ پنهنجي سينگار کي ظاهر نه ڪن. (۳۱). ۽ فرمايو: پنهنجن گهرن ۾ سڪون سان ٽڪيون رهو ۽ پراڻي جاهليت جي بي پردگيءَ وانگر نه رهو. (سورة الاحزاب). ۽ فرمايو: خيمن اندر پردي ۾ رهندڙ حورون آهن. (سورة الرحمٰن: ۷۲). جنت ۾ حورون به پردو ڪنديون، جتي برائيءَ جو ڪو خدشو به نه هوندو. حقيقت ۾ پردو ته عورت جي حيا ۽ حسن آهي.", "taaruf.057": "اڄ هن فتني ڀريل دور ۾، جڏهن بي پردگي ۽ بي حيائي عروج تي آهي، اسان کي پنهنجي پاڪيزه ڌيئرن جي عفت جي تحفظ لاءِ گڏجي بي پردگيءَ جي هن بڇڙي رسم جو خاتمو ڪرڻو پوندو، ۽ پنهنجي نُنهن ۽ ڌيئرن کي شرعي پردو ڪرڻ جي ترغيب ڏيڻي پوندي. اڄ جون روشن خيال عورتون چون ٿيون ته پردو ته نظر جو هوندو آهي. جڏهن صحابيات ڪريم آقا ﷺ کان پردو ڪيو ۽ الله تعاليٰ پنهنجي پاڪ ڪلام ۾ هر غير محرم کان پردو ڪرڻ جو حڪم فرمائي ڇڏيو، ته پوءِ اڄ جي هن روشن خياليءَ جي ڪهڙي حيثيت رهجي وڃي ٿي.", "taaruf.058": "ان کان علاوه! اسان کي پنهنجي ٻارن کي جيترو ممڪن ٿي سگهي موبائل فونن جي منفي استعمال کان به بچائڻو پوندو. اڄ اهو ئي دور اچي چڪو آهي جنهن بابت آپ ﷺ فرمايو هو ته فتنا گهرن جا دروازا ڀڃي اندر داخل ٿي ويندا. موبائل فون ۽ ٽي وي ئي اهو فتنو آهن جن ذريعي گهر ويٺي ٻارن تائين بي حيائي ۽ برائيءَ جي پهچ ممڪن ٿي وئي آهي. اڄ واٽس ايپ اسٽيٽس ۽ سوشل ميڊيا تي ناچ گاني ۽ لهو و لعب کان سواءِ ڪجهه نظر نٿو اچي. خدا جي واسطي! پاڻ کي ۽ پنهنجي گهر وارن کي ان باهه کان بچايو جنهن جو ٻارڻ ماڻهو ۽ پٿر آهن.", "taaruf.059": "توهان هن نيڪ ڪم ۾ اسان جا مددگار ڪيئن ٿي سگهو ٿا", "taaruf.060": "جيڪڏهن توهان اسان جي هن تحريڪ جي مقصدن سان متفق آهيو ته اسان جي نامزد ڪيل ڪارڪنن سان رابطو ڪري رڪنيت فارم ۽ ڊاڪ لفافو بلڪل مفت حاصل ڪري هن تحريڪ جي ميمبرشپ اختيار ڪري سگهو ٿا.", "taaruf.061": "جيڪڏهن توهان باقاعده ميمبر ٿيڻ نٿا چاهيو ته هن تحريڪ جي ڦهلاءَ لاءِ هن ڪتابچي ۾ ڏنل گذارشن تي جيترو به ٿي سگهي انفرادي يا اجتماعي ڪوشش ڪري اسان جو ساٿ ڏيو.", "taaruf.062": "ماخذ: ڪتابچو «تحریک اتباعِ سنت پاکستان کا تعارف اور اس کے مقاصد»", "baani.001": "باني ۽ اڳواڻ جو تعارف", "baani.002": "تحريڪ اتباعِ سنت پاڪستان جو باني", "baani.004": "شروعاتي حالتون ۽ تعليم", "baani.005": "تحريڪ اتباع سنت پاڪستان جا باني ۽ قائد، پيرِ طريقت کرامت علی بن محمد الیاس رزاقی جو تعلق گوٹھ محمد ابڑو، صوبه سنڌ سان آهي. نسب جي لحاظ کان آپ راجپوت قوم سان تعلق رکن ٿا. شروعاتي تعليم کانپوءِ 1983-84ع ۾ ٹنڈو آدم نیو علی گڑھ کالج مان بي ڪام ڪيائون، ۽ نوڪريءَ دوران ايم اي اڪنامڪس کانپوءِ ايل ايل بي ڪيائون.", "baani.006": "نوڪري", "baani.007": "1985ع ۾ آپ پاڪستان پوسٽ ۾ سينيئر ڪلارڪ ڀرتي ٿيا. 2013ع ۾ اسسٽنٽ سپرنٽينڊنٽ پوسٽل سروسز جي حيثيت ۾، پنهنجي پيشوا جي حڪم سان، رٽائرمينٽ جي مقرر وقت کان ڏهه سال اڳ رٽائرمينٽ وٺي سلسلهٔ عاليه جي ترويج ۾ ڏينهن رات مشغول ٿي ويا.", "baani.008": "بيعت ۽ خلافت", "baani.009": "مذهبي گهراڻو هجڻ سبب شروع کان ئي مذهب ڏانهن رجحان رهيو، ۽ پنهنجي بزرگن جي تقليد ۾ 1981ع ۾ سلسلهٔ عاليه نقشبنديه جي عظيم روحاني شخصيت قطبِ عالم حضرت سائیں عبدالرزاقؒ جي دستِ اقدس تي بيعت ٿيا. ان وقت ڪاليج ۾ پڙهندا هئا پر مٿي تي هميشه ٽوپي رکندا هئا ۽ نمازن جي پابنديءَ جو خاص خيال رکندا هئا. ان کانپوءِ آپ پنهنجي پير ۽ مرشد امام الذاکرین حضور محمد عظیم اللہ رزاقی نقشبندیؒ جي خدمت ۾ وقت بوقت ڪافي عرصو گذاريو ۽ سندن فيض ڀري صحبت مان فيضياب ٿيا. نومبر 2006ع ۾ پير ۽ مرشد آپ کي پنهنجي خلافت ۽ نيابت سان مشرف فرمايو.", "baani.010": "ديني خدمتون", "baani.011": "هر سال وڏي پيماني تي عرسِ مبارڪ جو اهتمام فرمائين ٿا. پير ڀائرن سان وڌ کان وڌ رابطو، وعظ ذريعي دين جي تبليغ ۽ ذڪرِ حبيب ﷺ جي محفلن جو انعقاد آپ جو طريقو آهي. دين ۽ سلسلي جو پيغام پهچائڻ لاءِ سوشل ميڊيا جو مثبت استعمال به ڪن ٿا، ۽ خلفاءِ راشدين، اهلِ بيتِ اطهار ۽ بزرگانِ دين جي وصال جي ڏينهن تي خاص طور آن لائن ٽرانسميشن جو اهتمام ڪرائين ٿا. ان ئي مشن تحت پاڪستان جي مختلف علائقن جو سفر به ڪندا رهن ٿا.", "baani.012": "آپ جي ڳوٺ ۾ 1972ع کان قائم مدرسه عربيه خالقيه رزاقيه جو انتظام به آپ وٽ آهي. ان کان علاوه پنهنجي ڳوٺ ۾ دانش ڪدهٔ عظيم مرڪزِ علم و عرفان به تعمير ڪرايو اٿن، جيڪو مرڪزي آفيس تحريڪ اتباع سنت پاڪستان، لائبريري مجدد الفِ ثانيؒ، زيرِ تعمير مسجد سيدنا صديقِ اڪبرؓ، ۽ يتيم ۽ مستحق ٻارن جي ديني ۽ جديد تعليم ۽ ڪفالت لاءِ مدرسي ۽ يتيم خاني تي مشتمل آهي. عورتن لاءِ به الڳ مدرسي جو اهتمام ڪيل آهي. ٻين پير ڀائرن کي به مدرسن جي قيام سان گڏوگڏ ذڪر ۽ نعت جي محفلن جي اهتمام جي ترغيب ڏين ٿا.", "baani.013": "تربيت جو طريقو", "baani.014": "آپ روايتي پيري مريديءَ کان هٽي، پنهنجي مرشدينِ ڪاملين جي طريقي موجب، پنهنجي مريدن ۽ هر ايندڙ کي هميشه توحيد، خدا جي خوف، الله تي توڪل ۽ نبي ڪريم ﷺ جي محبت ۽ اتباع جو درس ڏين ٿا. مدرسن جي قيام ۽ ديني تعليم سان گڏوگڏ جديد تعليم جو به خاص انتظام ڪرائين ٿا. مشائخِ عظام جي ڪشف ۽ ڪرامتن تي ٻڌل ڪتابن بدران، جن ۾ يقينن ڪافي حد تائين مبالغو به هوندو آهي، انهن بلند مرتبي وارن مشائخن جون پنهنجون تصنيفون پڙهڻ جي هدايت ڪن ٿا.", "baani.015": "تصنيفون", "baani.016": "سلسلهٔ عاليه ۾ وڌيڪ علمي ذوق پيدا ڪرڻ لاءِ شريعت ۽ طريقت تي ٻڌل ڏهن کان وڌيڪ ڪتاب لکي ۽ ترتيب ڏئي چڪا آهن. پنهنجي لکيل نعتن ۽ منقبتن جو مجموعو «حروفِ ثناء» جي نالي سان ڇپائي چڪا آهن. هن سلسلي کي وڌيڪ فروغ ڏيڻ لاءِ ڏينهن رات ڪوشان آهن.", "baani.017": "لکندڙ: انجینئر شعیب عالم عظیمی مجددی", "baani.018": "صاحبزادن جو تعارف", "baani.019": "صاحبزادہ اویس العظیم عظیمی", "baani.020": "آپ سنڌ يونيورسٽيءَ مان گريجوئيشن ڪئي آهي ۽ هن وقت سنڌ پوليس ۾ وائرليس آپريٽر طور خدمتون سرانجام ڏئي رهيا آهن. آپ محفلن ۾ شرڪت ڪن ٿا ۽ ڏاڍي پرجوش انداز ۾ نقابت فرمائين ٿا.", "murshideen.001": "ڪامل مرشدن جو تعارف", "murshideen.002": "شمس الکونین خواجہ محمد عبدالخالق نقشبندیؒ<span class=\"mk-hint\">تعارف پڙهو ▾</span>", "murshideen.003": "بيواهن جو مونس، يتيمن جو دستگير، فاتحِ قاديانيت<br>شمس الکونین خواجہ محمد عبدالخالق شمس العرفانی نقشبندیؒ", "murshideen.004": "شروعاتي حالتون", "murshideen.005": "آپ شمس العرفان خواجہ قادر بخشؒ جا شهزادا ۽ شمس العارفین غوثِ زماں سائیں عبدالرزاقؒ جا پير ۽ مرشد آهن. آپ جو لقب ابوسعد آهي. ۷ شوال ۱۲۷۰ھ / ۱۸۵۴ع جمعة المبارڪ جي ڏينهن صبحِ صادق جي وقت جہانخیلاں ۾ پيدا ٿيا. پاڻ فرمائين ٿا ته ٽن سالن جي عمر ۾ مون کي ملائڪن ۾ قطبِ زمان سڏيو ويندو هو، ۽ ستن سالن جي عمر ۾ نبي ڪريم ﷺ ۽ سڀني انبياءِ ڪرام مون کي پنهنجون زبانون مبارڪ چوسايون ۽ فرمايو ته اسان سڄو علم توکي ڏئي ڇڏيو. اڃا آپ لڳ ڀڳ ٽن سالن جا ئي هئا ته والد بزرگوار شمس العرفان خواجہ قادر بخشؒ شهادت ماڻي.", "murshideen.006": "دين جي علم جو حصول", "murshideen.007": "حديث جي علم لاءِ سہارنپور ۾ مولانا احمد علی محدثؒ جي خدمت ۾ حاضر ٿيا. مولانا حسین احمد کانپوریؒ ۽ پیر مہر علی شاہ گولڑویؒ آپ جا هم سبق هئا. ان کانپوءِ دهليءَ ۾ مولوی کریم اللہ صاحبؒ ۽ مولوی سعید احمدؒ کان دينيات جي علمن تي پوريءَ طرح عبور حاصل ڪيائون. الله تعاليٰ جي فضل ۽ ڪرم سان آپ علمن ۽ ڪمالن جو خزانو هئا. جڏهن ڪنهن به قسم جو ڪو مسئلو آپ جي سامهون پيش ڪيو ويندو هو ته وضاحت سان، حوالن سميت، اهڙيءَ طرح بيان فرمائيندا هئا جو وڏا وڏا مفتي صاحب حيران رهجي ويندا هئا. خليفو مولوی عبدالکریم جسری صاحبؒ پنهنجي ڪتاب «خالقیہ» ۾ لکن ٿا ته خواجه صاحبؒ موجوده زماني ۾ ڪامل ۽ اڪمل شخص آهن ۽ مولوين جي جماعت جا هڪ وڏا عالم آهن.", "murshideen.008": "دين جي مبلغ جي حيثيت ۾", "murshideen.009": "آپؒ گهڻو ڪري بيهي تقرير فرمائيندا هئا. آپؒ جا شروعاتي ملفوظات ۽ بيان رشد و هدايت، مذهب جي ترغيب ۽ اسلام جي اشاعت تي ٻڌل هئا. جڏهن الله تعاليٰ آپؒ کي خدمتِ خلق جو حڪم فرمايو ته خدمت جي منصب سان معمور ٿي مخلوق جي خدمت لاءِ ڪمر ٻڌي، ۽ خاص طور ٻه خدمتون، يعني بيواهن جو نڪاح ۽ يتيمن ۽ مسڪينن جي خدمت، انجام ڏنيون.", "murshideen.010": "مرشد جي طلب ۾ سياحت", "murshideen.011": "ڇهن سالن کان پنجٽيهن سالن جي عمر تائين آپ جو گهڻو وقت سفر ۾ گذريو. ان طلب ۾ سڄي هندستان، افغانستان، ايران ۽ عرب وغيره ۾ سفر ڪيائون. (پاڻ فرمائين ٿا:) پیر پٹھان شاہ سلیمان تونسویؒ، ڪعبي شريف ۾ حاجی امداد اللہ مہاجر مکیؒ ۽ مديني شريف ۾ صاحبان عبدالغنی ۽ مولانا محمد عمرؒ ۽ ٻين بزرگن جي خدمت ۾ به پهتس، پر بيعت لاءِ سوال هن شرط تي ڪندو هوس ته جيڪڏهن آپ منهنجي سڄي بدن مان الله، الله جاري ڪرائي ڇڏيو ته بيعت ٿيندس. مشائخ جڏهن اهو سوال ٻڌندا هئا ته هٿ ڇڪي وٺندا هئا.", "murshideen.012": "سلسلهٔ قادريه ۾ بيعت ۽ خلافت", "murshideen.013": "فرمائين ٿا: الٰہ آباد ۾ شیخ احمد بخاری قادریؒ جي خدمت ۾ پهتس ته مون کي ڏسندي ئي فرمايائون: «برو برو دیگر را بگیر» — وڃ، ڪو ٻيو رستو ڏس. مان بيتابيءَ سان ڊوڙي سندن قدمن سان چنبڙي ويس. ڏاڍي شفقت سان منهنجو مٿو مٿي ڪري سيني سان لاتائون، ۽ بيعت فرمائڻ لاءِ جڏهن شيخ صاحبؒ پنهنجي دستِ مبارڪ ۾ منهنجو هٿ ورتو ۽ توجه ڏني ته مان بيهوش ٿي ويس. ان وقت منهنجي هر وار مان الله جاري هو. ان کي ئي قرآن مجيد ۾ ذڪرِ ڪثير فرمايو ويو آهي ۽ ان کي سلطان الاذڪار چوندا آهن.", "murshideen.014": "ڇهن مهينن جي خدمت کانپوءِ هڪ ڏينهن سڀني درويشن جي سامهون شيخ صاحب خلافت جي دستار منهنجي مٿي تي ٻڌڻ چاهي ۽ فرمايائون ته ڇا هي ان لائق آهي يا نه؟ ڪنهن جي جواب ڏيڻ کان اڳ مون عرض ڪيو ته هن ڳري بار جو کڻڻ ته ڏاڍو ڏکيو لڳي ٿو، پر هٿ ٻڌي التجا ڪريان ٿو ته منهنجي دلي مراد پوري ٿي وڃي. فرمايائون: اها ڪهڙي آهي؟ عرض ڪيم ته پنهنجو وجد بخشي ڏيو. آپؒ اهو ٻڌي سڀني درويشن کي فرمايو: توهان هميشه چوندا هئا ته شيخ صاحب کي هن ڇوڪري سان ڏاڍي محبت آهي، هاڻي ٻڌايو ته جيڪو سوال هن ڇوڪري ڪيو آهي، ڇا ڪڏهن توهان جي دل ۾ به اهو خيال آيو؟ اهو ٻڌي سڀني درويشن تي وجد طاري ٿي ويو. فرمايائون: رمز داني ان جو ئي نالو آهي. پوءِ خلافت جي دستار پنهنجي دستِ اطهر سان ٻڌي فرمايائون: وڃ، سلسلهٔ نقشبنديه ۾ بيعت ڪري پنهنجي والد بزرگوار جو نالو روشن ڪر، جتي تون هوندين اتي مان تو سان گڏ هوندس.", "murshideen.015": "سلسلهٔ نقشبنديه ۾ بيعت ۽ خلافت", "murshideen.016": "شيخ صاحب آپ کي جالندھر وٺي ويا ۽ آپ جي والد بزرگوار شمس العرفانؒ جي پيشوا حاجی حافظ محمود جالندھریؒ کان سلسلهٔ نقشبنديه ۾ بيعت ڪرايائون. ڇو ته والد بزرگوار آپ کي وصيت ڪئي هئي ته پهريان ست سال منهنجي مزار تي ويهجانءِ ۽ پنهنجي ۽ منهنجي والده جي خدمت ڪجانءِ، تنهنڪري سلوڪِ نقشبنديه جي تڪميل جي مقصد سان والد بزرگوار جي مزار مبارڪ تي روزانو حاضر ٿيندا هئا ۽ مزار مبارڪ مان روحاني تربيت حاصل ڪندا رهيا. آپؒ سلوڪِ مجدديه ٿوري عرصي ۾ طئي فرمايو ۽ حاجي صاحبؒ آپ کي خلافت جي دستار عطا فرمائي.", "murshideen.017": "شمس الکونین جون سنت کي زنده ڪرڻ جون خدمتون", "murshideen.018": "۱. بيواهن جو نڪاح", "murshideen.019": "خواجه صاحب پنهنجي ڪتاب «سرمایۂ سہاگن» ۾ فرمائين ٿا ته لڳاتار چئن سالن جي اڻٿڪ محنت کانپوءِ ۲۱ مارچ کان ۲۳ مارچ ۱۸۹۲ع، مطابق ۱۳۰۹ھ، قصبہ کلانور ضلع رہتک ۾ جلسهٔ اسلاميه ڪرايو، جنهن ۾ تيرهن هزار ست سؤ پنجهٺ ڪرسيون رکيون ويون ۽ هڪ تمام وڏو اسٽيج سجايو ويو، جنهن تي ڊپٽي ڪمشنر رہتک، وڏن وڏن آفيسرن ۽ علماء ۽ مشائخن کي ويهاريو ويو. کلانور جي وڏن وڏن گهراڻن ۾ بيواهن جا نڪاح تيزيءَ سان ٿيڻ لڳا. تيرهن سؤ سالن کانپوءِ هن فرمانِ الاهي «پنهنجي بيواهن جا نڪاح ڪريو» (القرآن) تي راجپوت قوم کي آماده ڪري بيواهن جي نڪاح جي مئل سنت کي زنده ڪرڻ جو شرف حاصل ڪيائون. ان کان اڳ راجپوت قوم ان کي بي غيرتيءَ جو ڪم سمجهندي هئي. تمام گهڻا پئسا غريبن ۽ فقيرن ۾ ورهايا ويا ۽ وليمي جي دعوت به سڀني کي ڏني وئي.", "murshideen.020": "معززين لوٽن ۾ پاڻي ۽ لوڻ وجهرائي عهد و پيمان ورتو ته اڄ کان اسان خوشيءَ ۽ رضامنديءَ سان هن هندوانه ۽ ڪفريه رسم کي ڇڏيو ۽ دل ۽ جان سان خدا ۽ رسول ﷺ جو حڪم منظور ڪيو. هاڻي هميشه بيواهن جا نڪاح ڪندا رهنداسين. جيڪڏهن ان تي ڪو عمل نه ڪندو ته ان سان سڀ ماڻهو ملڻ جلڻ ۽ رشتو ناتو ڇڏي ڏيندا. جيڪو به بيواهه جو نڪاح ڪندو، اسان ان ۾ خوشيءَ سان شريڪ ٿينداسين، جيئن ڪنواري ڇوڪريءَ جي نڪاح ۾ شريڪ ٿيندا آهيون، ۽ جيڪو شخص عيب ۽ طعنو سمجهي شريڪ نه ٿيندو ته برادري ان کي خارج ڪري ڇڏي. جيئن اسان بيواهن جو ٻيو نڪاح جاري ڪيو، تيئن اسان شرعي پردو جاري ڪنداسين، يعني جيڪي ماڻهو غير محرم آهن انهن کان پنهنجي نُنهن ۽ ڌيئرن کي جيترو ممڪن هوندو پردو ڪرائڻ جي ڀرپور ڪوشش ڪنداسين.", "murshideen.021": "۲. يتيمن جي پرورش", "murshideen.022": "آپؒ جتي به ويندا هئا، بيواهن جي نڪاح جي تبليغ سان گڏوگڏ يتيمن جي پرورش جي به تلقين فرمائيندا هئا، ڇو ته يتيمن جو بيواهن سان گهرو تعلق آهي. فرمائيندا هئا: يتيم پرور کي جيڪا خوشخبري نبي ڪريم ﷺ ڏني آهي، اها ڪنهن عابد، زاهد، شهيد يا ڪنهن وڏي کان وڏي نيڪ شخص لاءِ نه ڏني آهي. فرمانِ مصطفیٰ ﷺ آهي: مان ۽ يتيم جي پرورش ڪندڙ جنت ۾ ائين گڏ هونداسين جيئن هي ٻه آڱريون. آپ ﷺ شهادت جي آڱر ۽ ان سان گڏ واري آڱر کي ملائي اشارو فرمايو. تنهنڪري آپؒ وٽ جيڪو ڪجهه بچندو هو، اهو سڀ يتيمن ۽ بيواهن ۾ ورهائي ڇڏيندا هئا.", "murshideen.023": "۱۵ جون ۱۹۰۵ع تي يتيم خانه خالقيه ۽ انجمن خالقيه جو قيام ٿيو. پوءِ قرآن پاڪ جي تعليم جو بندوبست ڪيو ويو. ان کانپوءِ ۱۹۰۶ع ۾ پرائمري، ۱۹۱۴ع ۾ مڊل ۽ ۱۹۲۵ع ۾ هاءِ اسڪول ۽ پوءِ انٽر ڪاليج منظور ٿيو. انهن ادارن مان هندو ۽ سک ٻار به فيضياب ٿيا. مسلمانن، برهمڻن، واڻين، سکن ۽ چمارن جا ٻار به پڙهندا هئا، ۽ آفريڪا مان به ٽي يتيم ٻار تعليم لاءِ آيا.", "murshideen.024": "ساڳيءَ طرح سید امیر حسین شاہ صاحب، رهواسي رحیم یار خان، اڻويهه مربع زمين آپؒ جي نالي ڪرائي ڇڏي ته جيئن آپؒ پنهنجو پڪو آستانو تعمير ڪرايو. پر آپؒ اها سموري زمين پنهنجي يتيم خاني جي نالي ڪرائي ڇڏي ۽ فرمايائون: اسان کي زمينن جي ضرورت ناهي. آپؒ پنهنجي رهائش هميشه ڪک جي ڇپر واري ڪچي گهر ۾ ئي رکي، پر يتيمن، مسافرن ۽ اسڪول جي ملازمن لاءِ پڪا گهر ٺهرايا. جيڪڏهن ڪنهن آفيسر سان ملندا هئا جيڪو در تي حاضر ٿيندو هو ته هڪ هٿ سان مصافحو ڪندا هئا. جيڪي آفيسر نذرانو پيش ڪندا هئا، اهو پاڻ نه رکندا هئا، بلڪه يتيم خاني ۾ جمع ڪرائي ڇڏيندا هئا ۽ ان کي فرمائيندا هئا ته توهان جو نذرانو يتيم خاني ۾ ان لاءِ جمع ڪرايو آهي ته جيئن ان جي بدلي ۾ خداوندِ ڪريم دنيا ۽ آخرت ۾ هزار ڀيرا وڌيڪ عطا فرمائي. جڏهن ڪو مهمان مٺائي وغيره آڻيندو هو ته سنت جي پيرويءَ ۾ پاڻ پنهنجي دستِ شفقت سان يتيمن ۽ درويشن ۾ ورهائي ڇڏيندا هئا.", "murshideen.025": "۳. تحفظِ ختمِ نبوت", "murshideen.026": "جڏهن مرزا غلام احمد قادیانی نبوت جي ڪوڙي دعويٰ ڪئي ته ۱۹۰۲ع ۾ مباهلي لاءِ هزارين اهلِ اسلام لاهور ۾ گڏ ٿيا. اهلِ سنت و جماعت طرفان ٽي اصحاب — شمس الکونین خواجہ محمد عبدالخالقؒ، پیر مہر علی شاہ گولڑویؒ ۽ انور شاہ کشمیریؒ — چونڊيا ويا. مرزا قادیانی مباهلي جي شرط رکي ته ميدان ۾ خالي قلم ۽ دوات رکي وڃي، قدرت منهنجي نبوت جي تصديق ڪندي. انهن حضرتن اها شرط قبول ڪئي. ٻئي ڏينهن مباهلي جي ميدان ۾ ماڻهو ٽولن جا ٽولا اچڻ شروع ٿيا ۽ اهي ٽيئي بزرگ به پهچي ويا، پر مرزا قادیانی ميدان ۾ اچڻ بدران قاديان ڀڄي ويو.", "murshideen.027": "ڊسمبر ۱۹۲۴ع ۾ آپؒ روضهٔ مبارڪ مجدد الفِ ثانيؒ سرهند شريف ۾ رهيل هئا. ضلع رنگ پور بنگال جي مسلمانن خط لکيو ته مرزا قادیانی جو پٽ مرزا بشیر الدین قادیانی مسلمانن کي مباهلي جو چئلينج ڏئي رهيو آهي، ڇا آپؒ مباهلي لاءِ تيار آهيو؟ جواب ڏنائون ته انهن شرطن تي مباهلي لاءِ تيار آهيان: (۱) هو مباهلي جي تاريخ جو پاڻ اعلان ڪري. (۲) مباهلي جي جاءِ هندستان جي ڪنهن وڏي شهر، مثلاً دهلي، لاهور، ڪلڪتي يا بمبئيءَ ۾ هجڻ گهرجي. (۳) مباهلو عام مجمعي ۾ ٿئي. جڏهن مرزا اهي شرطون ٻڌيون ته پنجاب ڀڄي ويو.", "murshideen.028": "۴. اول وقت ۾ نماز جو اجراء", "murshideen.029": "۱۹۲۵ع ۾ آپؒ خواب ۾ ڏٺو ته هڪ زماني جي مشهور بزرگ تي سخت عذاب ٿي رهيو آهي. معلوم ٿيو ته اهو عذاب نمازون دير سان ادا ڪرڻ ۽ جماعت ڇڏڻ سبب ٿي رهيو آهي. تڏهن کان آپ سڀني نمازن، خاص ڪري فجر ۽ ظهر جي ادائگيءَ ۾ ڏاڍي جلدي فرمائڻ لڳا، ۽ حنفي مسلڪ جي وقتن موجب نماز جو وقت شروع ٿيندي ئي باجماعت نماز جو اهتمام فرمائيندا هئا.", "murshideen.030": "سورة الماعون ۾ ارشادِ باري تعاليٰ آهي: <span class=\"kk-ar\" style=\"display:block\">فَوَيْلٌ لِّلْمُصَلِّيْنَ ۝ الَّذِيْنَ هُمْ عَنْ صَلَاتِهِمْ سَاهُوْنَ</span> — انهن نمازين لاءِ ويل، يعني جهنم جي هڪ کڏ جو عذاب آهي، جيڪي پنهنجي نمازن ۾ غفلت ڪن ٿا. نبي ڪريم ﷺ ارشاد فرمايو: اول وقت ۾ نماز جي ادائگي حق تعاليٰ جي خوشنوديءَ جو سبب آهي.", "murshideen.031": "امام غزالیؒ، سیدنا شیخ عبدالقادر جیلانیؒ، امامِ ربانی مجدد الفِ ثانیؒ ۽ شاہ غلام علی دہلویؒ جهڙا بلند مرتبي وارا مشائخ به اول وقت ۾ نماز ادا فرمائيندا هئا ۽ پنهنجي مريدن کي به ان جي تلقين فرمائيندا هئا. ان سان گڏ هر سمجهدار شخص اها ڳالهه چڱيءَ طرح سمجهي سگهي ٿو ته رب جو حڪم ٿي وڃڻ کانپوءِ بنا شرعي عذر جي نماز جي ادائگيءَ ۾ دير ڪرڻ محبت جي دعويٰ کان پري ۽ حڪم عدوليءَ جي ويجهو آهي، جڏهن ته ٻانهو اهو ئي محبوب هوندو آهي جيڪو وقت ٿيندي ئي پنهنجي رب جي حضور سجدي ۾ ڪري پوي. تنهنڪري اول وقت ۾ نماز ادا ڪرڻ جي ڪوشش ڪرڻ گهرجي.", "murshideen.032": "وصال مبارڪ", "murshideen.033": "لڳ ڀڳ رات جو هڪ وڳي سائیں صاحبؒ کي جاڳايائون ۽ فرمايائون: مون کي وضو ڪرائي تهجد جا نفل پڙهاءِ. نفلن کانپوءِ سجدي ۾ ڪري دعا گهريائون: اي الله! مون کي جان ڪڍڻ جي تڪليف نه ڏجانءِ ۽ سجدي جي حالت ۾ شهادت جو درجو عطا فرمائجانءِ. دعا کانپوءِ فرمايائون: عبدالرزاق! هاڻي مون کي سخت بي چيني آهي، دٻائيندو رهه. اهڙيءَ طرح فجر جو وقت ٿي ويو، آپؒ وضو ڪري فجر جون سنتون ادا ڪيون. جماعت کڙي ٿي وئي. آپؒ سان گڏ سید دین علی شاہؒ، سائیں عبدالرزاقؒ ۽ مولوی سراج الدین مقتدي هئا. ٻي رڪعت جي آخري سجدي ۾ اوچتو سڄي ڇت ڪري پئي، ۽ ۷ محرم الحرام ۱۳۵۰ھ تي ۸۰ سالن جي عمر مبارڪ ۾ آپؒ پنهنجي خالقِ حقيقيءَ سان وڃي مليا.", "murshideen.034": "شمس العارفین سائیں عبدالرزاق خالقی نقشبندیؒ<span class=\"mk-hint\">تعارف پڙهو ▾</span>", "murshideen.035": "شمس العارفین، سراج السالکین<br>قطبِ عالم حضرت سائیں عبدالرزاق خالقی نقشبندیؒ", "murshideen.036": "ڪشف ۽ ڪرامتون ته هيٺئين درجي جي ڳالهه آهي، اصل شيءِ اتباعِ سنت ۽ شريعتِ مطهره جي پابندي آهي، ڇو ته مريدن کي پيشوا جو عمل ڏسي ان جي پيروي ڪرڻي هوندي آهي. (شمس العارفينؒ)", "murshideen.037": "اڪثر فرمائيندا هئا: شريعت ٻج آهي، جيڪڏهن ٻج ئي خراب هجي ته وڻ ڪيئن ٺيڪ ٿيندو. اول به شريعت آهي ۽ آخر به شريعت. جيڪڏهن ڪو هوا ۾ اڏامندو به اچي پر شريعت جو وار برابر به ڇڏيندڙ هجي ته اهو جادوگر ٿي سگهي ٿو پر الله وارو نٿو ٿي سگهي.", "murshideen.038": "ولادت باسعادت", "murshideen.039": "آپؒ جي فرمودات مطابق آپ جي ولادت باسعادت ۱۸۹۰ع ۾ ٿي. ولادت کان پوءِ آپ جي ڏاڏي نيڪ بختي ۽ وڏي ڄمار لاءِ آپ کي مسجد ۾ موڪلي ڇڏيو. آپ فرمائيندا هئا ته الله تعاليٰ جو احسان آهي جو سڄي عمر مسجدن ۾ ئي گذري وئي.", "murshideen.040": "ابتدائي تعليم", "murshideen.041": "جڏهن آپ جي عمر پنج ڇهه سال ٿي ته ان ئي وقت پنج وقتي نماز ۽ ست اٺ سالن جي عمر کان تهجد جي نماز پابنديءَ سان ادا ڪرڻ شروع ڪئي، جيڪا الله تعاليٰ جي فضل سان آخري دم تائين قضا نه ٿي.", "murshideen.042": "جڏهن آپ تهجد جي نماز شروع ڪئي، تڏهن آپ جي عمر فقط ست سال هئي.", "murshideen.043": "نه ڪڏهن تڪبيرِ اوليٰ ڇٽي ۽ نه ڪا نماز قضا ٿي، اي منهنجا سائیںؒ پيا، تنهنجي ڪهڙي ڳالهه آهي!", "murshideen.044": "ابتدائي تعليم مدرسه ڪلانور ۾ حاصل ڪئي. ٻئي درجي کان پوءِ مجذوبانه حالت سبب اسڪول ڇڏي ڏنو. قرآن شريف مسجد جي امام حافظ عبدالرحمٰن صاحب کان پڙهيو.", "murshideen.045": "خواجه صاحبؒ جي خدمت ۾ حاضري", "murshideen.046": "بزرگانِ دين فرمائين ٿا ته جيڪو اهو چاهي ته هو الله جو مقرب بڻجي ته اهو اولياءُ الله جي صحبت اختيار ڪري.", "murshideen.047": "پوءِ جڏهن آپ جي عمر مبارڪ ٻارهن سال ٿي ته آپؒ جا والد آپ کي خواجه صاحبؒ جي خدمت ۾ وٺي ويا. خواجه صاحبؒ آپ کي گود ۾ کنيو ۽ پيار ڪيو. آپؒ جي والد صاحب عرض ڪيو ته هي هر وقت روئيندو ۽ قرآن شريف پڙهندو رهي ٿو ۽ ڪنهن سان ڳالهه نٿو ڪري، بس ايترو ٿي پوي ته هن کي کائڻ پيئڻ، ڪپڙا پائڻ ۽ ڳالهائڻ جو شعور اچي وڃي. خواجه صاحبؒ فرمايو: شادي به ٿيندي، اولاد به ٿيندو، نوڪري به ڪندو ۽ سردار به ٿيندو، هن جو نالو نبي ڪريم ﷺ جي مقبول ٻانهن جي فهرست ۾ درج ٿي چڪو آهي. آپؒ پاڻ فرمائين ٿا ته خواجهؒ صاحب جي فيض واري نگاهه سان مون تي جيڪا حالت گذري اها بيان کان ٻاهر آهي. ان ئي دوران آپؒ خواجه صاحبؒ جي هٿ تي بيعت ٿي چڪا هئا.", "murshideen.048": "سلوڪ جون منزلون طئي ڪرڻ", "murshideen.049": "حضور سائیںؒ جيءَ فرمايو: مان ۴۰ سال خواجه صاحبؒ جي خدمت ۾ رهيس پر سندن سامهون ڪڏهن به نه ڳالهايم. هڪ ڏينهن خواجه صاحبؒ منهنجي پٺيءَ تي سوار هئا ۽ نعلين مبارڪ سيد دين علي شاهه صاحبؒ کنيون بيٺا هئا. آپؒ روئندي هن طرح دعا فرمائي:", "murshideen.050": "يا الله! جيترو مان هن عبدالرزاق مان خوش آهيان، تون به ايترو ئي خوش ٿي وڃ، جيتري هن منهنجي خدمت ڪئي آهي مخلوق به هن جي ايتري ئي خدمت ڪري.", "murshideen.051": "هڪ دفعي سيد دين علي شاهه صاحبؒ خواجه صاحبؒ کي عرض ڪيو ته حضور! جيڪڏهن عبدالرزاق فوج ۾ هجي ها ته اڄ هي به سردار هجي ها. آپؒ اٿي ويٺا ۽ فرمايو: شاهه جي! توهان ڇا ٿا سمجهو، فوجي سردار ته هن جي پيرن ۾ رلندا. آپؒ پاڻ فرمائيندا هئا ته نه مون ۾ علم آهي، نه تسبيح ڦيرائي ۽ نه ورد وظيفا ڪيا، هي سڀ خواجهؒ صاحب جي صحبت، نگاهه ۽ دعا ۽ برڪت جو فيض آهي. مون ڪڏهن به خواجه صاحبؒ جي سامهون اک کڻي به نه ڏٺو ۽ نه ئي ڪڏهن آپؒ جي سامهون ڳالهايم.", "murshideen.052": "ڇٽيهه سال تون شيخ وٽ رهئين، شيخ جو ديدار ئي تنهنجو وظيفو هو.", "murshideen.053": "آخري ساهه تائين تون جدا نه ٿئين، اي منهنجا سائیں پيا، تنهنجي ڪهڙي ڳالهه آهي!", "murshideen.054": "يتيمن جي پرورش", "murshideen.055": "يتيمن جي پرورش ۾ آپ جو ڪو ثاني نه هو. سماج جي ٺڪرايل مصيبت زده يتيم ٻارن جي مدد ۽ سهائتا لاءِ هر وقت بيچين ۽ پريشان نظر ايندا هئا.", "murshideen.056": "ان سلسلي ۾ حافظ عليم الدين صاحب بيان ڪيو ته ۱۹۶۵ع ۾ حضور سائیںؒ جي حج تان واپس تشريف کڻي آيا ته اسين گهڻا ماڻهو ديپالپور شريف کان حضور جي استقبال لاءِ اوڪاڙه اسٽيشن تي آياسين. موج دين رزّاقي گلاب جي گلن جو هار کڻي آيو. اسان حضور کي گاڏيءَ مان لاٿو. موج دين حضور جي ڳچيءَ ۾ هار وجهڻ چاهيو پر حضور اهو هار موج دين جي ڳچيءَ ۾ وجهي ڇڏيو ۽ فرمايو: هي فضول خرچي آهي، ڏيکاءُ آهي. ايترا پئسا يتيم خاني ۾ جمع ڪرائي ڇڏين ها ته بهتر هو.", "murshideen.057": "فرمائيندا هئا ته يتيم سان اهڙو سلوڪ ڪرڻ گهرجي جو هن کي يتيميءَ جو ذرو به احساس نه ٿئي. جيڪڏهن ڀيک گهرائي پالڻو آهي ته پوءِ اهي پاڻ به پنهنجو پيٽ پالي سگهن ٿا، توهان جو ڪهڙو احسان؟ بلڪه يتيمن کان چندو گهرائڻ ۽ پوءِ پاڻ به استعمال ڪرڻ ٻئي حرام آهن.", "murshideen.058": "يتيم ٻارن جي مستقل بحاليءَ لاءِ ملڪ جي مختلف هنڌن تي لکين رپين جي خرچ سان دار الشفقت جي نالي سان يتيم خانا ۽ انهن سان گڏ مسجدون ۽ تعليمي ادارا تعمير ڪرايا. انهن يتيم خانن ۾ رهندڙ سوين يتيم ۽ لاوارث ٻارن کي ديني تعليم سان گڏوگڏ عصري ۽ ووڪيشنل تعليم به ڏني ويندي هئي، ۽ ائين کين سماج تي بار بڻجڻ بدران عزت ۽ وقار واري زندگي گذارڻ جي لائق بڻايو ويندو هو. هي ادارا حڪومت وٽ باقاعده رجسٽرڊ ۽ منظور ٿيل هئا ۽ انهن ۾ بورڊ جي نگرانيءَ هيٺ امتحان ورتا ويندا هئا.", "murshideen.059": "آپؒ پنهنجي ابا ڏاڏا واري زرعي زمين پنهنجي اولاد ۾ ورهائي ڇڏي هئي ته جيئن هو عزت سان گذر سفر ڪري سگهن، ۽ باقي سموري شهري ملڪيت يتيم خاني جي نالي هبه ڪري ڇڏي. ايتري قدر جو وصال کان اڳ نذراني جا هڪ لک ٽيويهه هزار رپيا به يتيم خاني جي فنڊ ۾ جمع ڪرائي ڇڏيا ۽ فرمايو: اولاد لائق ٿيو ته پاڻ ٺاهي وٺندو، نالائق ٿيو ته اڳيون به ضايع ڪري ڇڏيندو. الله جي راهه ۾ خرچ ڪرڻ گهرجي جيڪو اڳتي ڪم اچي.", "murshideen.060": "خطاب سراج السالڪين", "murshideen.061": "رسالدار محمد لقمان رزّاقي صاحب بيان ڪن ٿا ته ذهن ۾ اڪثر اهو سوال ايندو هو ته الله تعاليٰ جي خاص ٻانهن کي مختلف قسم جا خطاب ڪيئن ملي ويندا آهن. هڪ ڏينهن فجر جي نماز کان ڪجهه دير اڳ مان مسجد ۾ ويٺو هوس ته ننڊ جهڙي ڪيفيت طاري ٿي. ڏٺم ته امامِ رباني مجدد الفِ ثانيؒ ۽ قبلهٔ عالم حضور سائیںؒ جي مسجد جي محراب جي سامهون بيٺا آهن. حضرت مجدد صاحبؒ سائیںؒ صاحب کي سيني سان لڳايو ۽ پوءِ فرمائڻ لڳا: اچو ته توهان کي سراج السالڪين جو ٺپو هڻي ڇڏيون. بس پوءِ اک کلي وئي ۽ ائين سوال جو جواب ملي ويو.", "murshideen.062": "خطاب شمس العارفين", "murshideen.063": "آپؒ هڪ دفعي سيد جماعت علي شاهؒ جي خليفي چراغ علي شاهؒ وٽ، جن جو مزار مبارڪ لاهور والٽن ۾ آهي، مراله شريف تشريف کڻي ويا. شاهه صاحبؒ پنهنجي پڳ لاهي ڳچيءَ ۾ وجهي ڇڏي ۽ ٻئي ٻانهون مٿي ڪري فرمائڻ لڳا ته مان ڇا ٻڌايان ته منهنجي گهر ڪير آيا آهن، شريعت منع ٿي ڪري، ائين سمجهو ته ڪيڙيءَ جي گهر نرائن اچي ويا آهن. ان تي حضور سائیںؒ جيءَ فرمايو: شاهه جي تمام وڏا درويش آهن، دنيا جي چوٿين حصي جا مالڪ آهن. شاهه جي فرمائڻ لڳا ته جي، آپؒ منهنجو راز کولي ڇڏيو، معافي ٿو گهران، مون کان به هاڻي رهيو نٿو وڃي، مان به آپ جو راز کولي رهيو آهيان، آپؒ سڄي دنيا جا مالڪ آهيو ۽ هن وقت هڪ ئي هڪ آهيو. هڪ دفعي شاهه صاحبؒ فرمايو ته حضور سائیںؒ جي جو خطاب شمس العارفين آهي.", "murshideen.064": "ڏکوئيندڙ وصال", "murshideen.065": "آپؒ بواسير جي آپريشن لاءِ ڪنعان ٽرسٽ اسپتال لاهور ۾ داخل هئا، جتي آپ جي کٽ پهرين صف ۾ وڇائي ويندي هئي ۽ مٽيءَ سان تيمم ڪرايو ويندو هو ۽ آپؒ ليٽي ليٽي اشارن سان باجماعت نماز ادا فرمائيندا هئا. ۲۴ مارچ ۱۹۸۲ع تي ٻيهر ڪنعان ٽرسٽ اسپتال لاهور ۾ داخل ٿيا.", "murshideen.066": "آخر اڱاري جي رات آپ تي استغراق طاري ٿيو ۽ لڳ ڀڳ ۲۰ ڪلاڪ استغراق جي حالت ۾ رهي، اربع جي ڏينهن شام جو ۴ وڳي، تاريخ ۳۱ مارچ ۱۹۸۲ع مطابق ۴ جمادي الثاني ۱۴۰۳ھ، لڳ ڀڳ ۹۵ سالن جي عمر مبارڪ ۾ پنهنجي خالقِ حقيقيءَ سان وڃي مليا. وصال وقت پنهنجن ٻنهي هٿن جون شهادت واريون آڱريون مٿي ڪيون ۽ ان سان گڏ زبانِ مبارڪ مان اسمِ ذات الله نڪتو. وصال کان پوءِ سڀني ڏٺو ته قلبِ سليم ذڪرِ الاهيءَ ۾ متحرڪ هو. وصال مبارڪ کان فوراً پوءِ ريڊيو پاڪستان لاهور تان هي اعلان ٿيو: آفتابِ طريقت لڳ ڀڳ هڪ صدي تائين چمڪي اڄ اربع ۳۱ مارچ ۱۹۸۲ع مطابق ۴ جمادي الثاني ۱۴۰۳ھ تي غروب ٿي ويو.", "murshideen.067": "جسدِ مبارڪ کي غسل ڏنو ويو ۽ وصيت مطابق ان چادر ۾ ويڙهيو ويو جيڪا شهادت وقت خواجه صاحبؒ جي جسم مبارڪ تي هئي، ۽ خواجه صاحبؒ جا موئي مبارڪ به آپؒ جي ڪفن ۾ رکيا ويا. وڏي ميڙ سبب آپ جي نمازِ جنازه ٽي دفعا پڙهائي وئي. جمعي جي ڏينهن ۲ اپريل تي وصيت مطابق جسدِ مبارڪ کي معلق حالت ۾ ڪاٺ جي صندوق ۾ رکي سپردِ خاڪ ڪيو ويو.", "murshideen.068": "خلفاءِ ڪرام ۽ سجادگان", "murshideen.069": "آپؒ جا مشهور خلفاءِ ڪرام ٽي آهن، جن جا اسماءِ گرامي هيٺ ڏجن ٿا:", "murshideen.070": "۱. امام الذاکرین حضور سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ، دربارِ عاليه عظیم نگر شریف ضلعو بہاولنگر.<br>۲. بے حد سوہنے خواجہ نور احمد خاں رزّاقی نقشبندیؒ، دربارِ عاليه لالہ موسیٰ شریف ضلعو گجرات.<br>۳. ايڊووڪيٽ حضور محمد شریف رزّاقی نقشبندیؒ، دربارِ عاليه سیل گاؤں ضلعو پاکپتن شریف.", "murshideen.071": "آپؒ جا ٻه شهزادا هئا، جن جا اسماءِ گرامي هيٺ ڏجن ٿا:", "murshideen.072": "۱. صاحبزادہ فقیر محمد رزّاقی نقشبندی، الله تعاليٰ آپ جو سايو گهڻي وقت تائين اسان جي سرن تي قائم رکي.<br>۲. صاحبزادہ بلال احمد رزّاقی نقشبندیؒ. آپ جو وصال ۲۰۲۵ع ۾ ٿيو هو. الله تعاليٰ آپ جا درجا بلند فرمائي.", "murshideen.073": "امام الذاکرین سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ<span class=\"mk-hint\">تعارف پڙهو ▾</span>", "murshideen.074": "امام الذاکرین، سراج السالکین، قطبِ دوراں<br>مظہرِ نورِ خدا قبلۂ عالم سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ", "murshideen.075": "ولادت ۽ ننڍپڻ", "murshideen.076": "شناختي ڪارڊ مطابق آپؒ يڪم جنوري ۱۹۳۴ع تي انڊيا جي ڳوٺ سيهواني ضلعي حصار ۾ راجپوت گهراڻي جي هڪ نيڪ سيرت فرد حاجي حسين علي صاحبؒ جي گهر پيدا ٿيا. والده ماجده جو تعلق ڍنڪوٽ جي محلي مير خان سان هو، جن جو ڪٽنب هن وقت ڳوٺ محمد ابڙو ۾ رهائش پذير آهي. آپ ننڍپڻ ۾ گهڻو بيمار رهندا هئا، خاموش رهندا هئا يا وري روئيندا رهندا هئا.", "murshideen.077": "بيعتِ طريقت", "murshideen.078": "سورة المائده ۾ ارشادِ باري تعاليٰ آهي: <span class=\"kk-ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوْٓا اِلَيْهِ الْوَسِيْلَةَ وَجَاهِدُوْا فِيْ سَبِيْلِهٖ لَعَلَّكُمْ تُفْلِحُوْنَ</span> اي ايمان وارؤ! الله کان ڊڄو ۽ ان ڏانهن وسيلو ڳوليو ۽ ان جي راهه ۾ مجاهدو ڪريو ته جيئن توهان ڪامياب ٿيو. (۳۵)", "murshideen.079": "پنهنجي بيعت ٿيڻ جو واقعو اسان جا پيشوا پاڻ هن طرح بيان فرمائيندا هئا ته جڏهن مان پنجين درجي ۾ پڙهندو هوس ته فوجي ڀرتي ڪرڻ لاءِ آيا ته مان به ٻين ڇوڪرن سان گڏ ڀرتي ٿي ويس. انهن ئي ڏينهن ۾ ڊونگه بونگه ۾ راؤ مراتب علي جي ڊيري تي حضور سائیںؒ جي تشريف فرما هئا. مان زيارت لاءِ حاضر ٿيس ته سائیںؒ جيءَ ان ئي وقت مون کي بيعت فرمائي ورتو.", "murshideen.080": "ان کان پوءِ حضور سائیںؒ جي سونڍا شريف تشريف کڻي آيا ته منهنجي والده آپ کي ڏسندي ئي چيو ته هي ته اهي ئي بزرگ آهن جيڪي انڊيا ۾ هڪ عامل مون کي منهنجي ننهن ۾ ڏيکاريا هئا. منهنجي والده رستي ۾ بيهي رهي ۽ سائیںؒ جيءَ کي عرض ڪيائين: مون عظيم الله ته گهڻو اڳ ئي آپ کي ڏئي ڇڏيو هو. سائیںؒ جيءَ فرمايو: ها، هي منهنجو ئي آهي. ۱۹۵۵ع ۾ حضور سائیںؒ جي مون کي پاڻ سان ديپالپور شريف وٺي ويا ۽ هڪ ڏينهن ڪپڙا ڌوئيندي گيرو رنگ جو ڍيلو گهرائي پنهنجن ڪپڙن کي رنڱڻ سان گڏ منهنجا ڪپڙا به گيرو رنگ سان رڱي ڇڏيا.", "murshideen.081": "منصبِ خلافت", "murshideen.082": "حضور سائیںؒ جيءَ طرفان خلافت جو منصب عطا ٿيڻ جو واقعو آپؒ هن طرح بيان فرمائيندا هئا: حضور سائیںؒ جي ديپالپور شريف جي مسجد ۾ تشريف فرما هئا. مان صبح جو حلقهٔ ذڪر کان پوءِ مسجد جي صحن ۾ وڃي ڪڻڪ صاف ڪرڻ لڳس. حضور سائیںؒ جيءَ مراقبي کان پوءِ مون کي ياد فرمايو ۽ پنهنجي سڄي ٻانهن جي ويڙهه ۾ وٺي ارشاد فرمايو: الله الله ڪرائيندا ڪريو. مون عرض ڪيو ته حضور سڀ ماڻهو چڱيءَ طرح الله الله ڪن ٿا. فرمايائون: پهريان انهن سڀني کي مريد ڪندا ڪريو، پوءِ الله الله سيکاريندا ڪريو. ان وقت مون تي ڏاڍو خوف طاري ٿيو، سڄي جسم تي پگهر اچي ويو. فرمايائون: خواجه صاحبؒ مون کي به اهڙي طرح فرمايو هو ته هيئن توجه ڏيندا ڪريو ۽ هيئن الله الله ڪرائيندا ڪريو.", "murshideen.083": "خطاب امام الذاڪرين", "murshideen.084": "هن ناچيز مؤلف پنهنجي ڳوٺ ۾ حضور سائیںؒ جي جي سالياني عرس مبارڪ جي سلسلي ۾ اشتهار ڇپائڻا هئا. ان ئي ڪشمڪش ۾ سمهي پيس ته حضور قبلهٔ عالمؒ جي نالي مبارڪ سان آپ جي شايانِ شان ڪهڙو لقب لکرايان. خواب ۾ ڏٺم ته ناچيز حضور سائیںؒ جي جي قبرِ انور وٽ بيٺو آهي ۽ آپؒ جي مزار جي چوڌاري جتي تائين منهنجي نظر پهچي ٿي هئي فرش کان عرش تائين نور ئي نور نظر اچي رهيو هو، ۽ آپ جي قبرِ انور مان آواز آيو: عظيم الله! امام الذاڪرين آهي.", "murshideen.085": "وصال مبارڪ", "murshideen.086": "آپ ڪافي عرصي جي بيماريءَ کان پوءِ ۱۴ جمادي الاول ۱۴۳۴ھ مطابق ۲۷ مارچ ۲۰۱۳ع اربع جي ڏينهن صبح جو اٺين وڳي سونڍا شريف ۾ ذڪر الله ڪندي لڳ ڀڳ ۸۳ سالن جي عمر ۾ پنهنجي خالقِ حقيقيءَ سان وڃي مليا. آپ جي ننڍي ڀيڻ حڪومت بي بي جي چوڻ مطابق وصال جي ويجهو آپؒ فرمايو ته حضور سائیںؒ جي منهنجي ڀرسان ويٺا آهن.", "murshideen.087": "آپ جي تدفين ۲۹ مارچ جمعة المبارڪ جي ڏينهن بهاولنگر روڊ تي ڊونگه بونگه کان ڪجهه اڳ سورج گنج موڙ تي آپ جي مسجد جي صحن جي ويجهو ڪئي وئي، جتي هن وقت سائیں حضورؒ جي مزارِ اقدس جي ڊزائن تي آپ جو روضهٔ اقدس زيرِ تعمير آهي. خدا جي مخلوق ڏينهن رات آپؒ کان فيضياب ٿي رهي آهي.", "murshideen.088": "تصويرون ۽ مزارن جو تفصيل جلد شامل ڪيو ويندو، ان شاءالله.", "mubalighin.001": "مبلغن جو تعارف", "mubalighin.002": "تصويرون ۽ وڊيوز جلد شامل ڪيون وينديون، ان شاءالله.", "markaz.001": "مرڪزي مرڪز", "marakiz.001": "ذيلي مرڪز ۽ مدرسا", "marakiz.002": "اسلام پور", "marakiz.003": "کوٹلی نجابت", "marakiz.004": "وہاڑی", "marakiz.005": "کوٹ مصری خان", "marakiz.006": "مہاجر گوٹھ", "marakiz.007": "گوٹھ ابڑو", "marakiz.008": "35 چک", "marakiz.009": "راؤ گڑھ", "marakiz.010": "باقي مرڪزن ۽ مدرسن جو تفصيل جلد شامل ڪيو ويندو، ان شاءالله.", "bayanat.001": "بيان", "bayanat.002": "ڪنهن به بيان تي دٻايو — وڊيو يوٽيوب تي هلندي.", "kutub.001": "ڪتاب", "kutub.002": "حرف حرف تاثير", "kutub.003": "<span>مؤلف:</span> باني ۽ قائد تحريڪ اتباع سنت پاڪستان، مذهبي اسڪالر ڪرامت علي رزّاقي عظيمي مجددي نقشبندي <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.004": "<span>معاونت:</span> انجنيئر شعيب عالم عظيمي مجددي (ايم اي علومِ اسلاميه)، <span class=\"lat\">HOD</span> اليڪٽريڪل ٽريڊ، گورنمينٽ ٽيڪنيڪل ٽريننگ انسٽيٽيوٽ لوڌران", "kutub.005": "صفحا: <span class=\"lat\">136</span>  • اشاعت: آڪٽوبر <span class=\"lat\">2026</span>", "kutub.006": "تحريڪ اتباع سنت پاڪستان جو تعارف ۽ ان جا مقصد", "kutub.007": "اسان جو مقصد شريعت ۽ سنت جو فروغ", "kutub.008": "<span>مؤلف:</span> باني ۽ قائد تحريڪ، پيرِ طريقت ڪرامت علي رزّاقي عظيمي نقشبندي <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.009": "صفحا: <span class=\"lat\">19</span>", "kutub.010": "صراط الفلاح فی الدنیا والآخرۃ", "kutub.011": "دنيا ۽ آخرت ۾ ڪاميابيءَ جو رستو", "kutub.012": "<span>مؤلف:</span> باني ۽ قائد تحريڪ اتباع سنت پاڪستان، پيرِ طريقت ڪرامت علي رزّاقي عظيمي نقشبندي <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.013": "<span>معاونت:</span> انجنيئر شعيب عالم عظيمي مجددي (ايم اي علومِ اسلاميه)، <span class=\"lat\">HOD</span> اليڪٽريڪل ٽريڊ، گورنمينٽ ٽيڪنيڪل ٽريننگ انسٽيٽيوٽ لوڌران", "kutub.014": "صفحا: <span class=\"lat\">83</span>  • اشاعت: مارچ <span class=\"lat\">2019</span>", "kutub.015": "دستورِ طريقت", "kutub.016": "جيڪو راهِ سلوڪ جي نالي سان مشهور آهي", "kutub.017": "<span>مؤلف:</span> باني ۽ قائد تحريڪ اتباع سنت پاڪستان، پيرِ طريقت، شيرِ مجدد بدرالهديٰ ڪرامت علي رزّاقي عظيمي نقشبندي <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.018": "<span>معاونت:</span> انجنيئر شعيب عالم عظيمي مجددي (ايم اي علومِ اسلاميه)، <span class=\"lat\">HOD</span> اليڪٽريڪل ٽريڊ، گورنمينٽ ٽيڪنيڪل ٽريننگ انسٽيٽيوٽ لوڌران", "kutub.019": "صفحا: <span class=\"lat\">129</span>  • اشاعت: آڪٽوبر <span class=\"lat\">2016</span>", "gallery.001": "تصويرن جي گيلري", "bait.001": "بيعت ۽ طريقت", "bait.002": "بيعتِ طريقت", "bait.003": "سورة المائده ۾ ارشادِ باري تعاليٰ آهي: <span class=\"kk-ar\" lang=\"ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوْٓا اِلَيْهِ الْوَسِيْلَةَ وَجَاهِدُوْا فِيْ سَبِيْلِهٖ لَعَلَّكُمْ تُفْلِحُوْنَ</span> اي ايمان وارؤ! الله کان ڊڄو ۽ ان ڏانهن وسيلو ڳوليو ۽ ان جي راهه ۾ مجاهدو ڪريو ته جيئن توهان ڪامياب ٿيو. (۳۵)", "bait.004": "شاهه ولي الله محدث دهلوي ارشاد فرمائين ٿا ته هن آيت ۾ وسيلي مان مراد مرشدِ ڪامل آهي.", "bait.005": "سورة لقمان ۾ ارشادِ باري تعاليٰ آهي: <span class=\"kk-ar\" lang=\"ar\" style=\"display:block\">وَاتَّبِعْ سَبِيْلَ مَنْ اَنَابَ اِلَيَّ</span> ۽ ان جي راهه جي پيروي ڪريو جنهن منهنجي طرف رجوع ڪيو. (۱۵)", "bait.006": "بيعتِ طريقت ۽ ارادت بابت سيدنا عباده بن صامت انصاريؓ فرمائين ٿا ته اسان رسول الله ﷺ سان هر آسانيءَ ۽ ڏکيائيءَ، هر خوشيءَ ۽ ناپسنديءَ ۾ آپ ﷺ جو حڪم ٻڌڻ ۽ اطاعت ڪرڻ ۽ آپ ﷺ جي ڪنهن به حڪم ۾ چون چرا نه ڪرڻ تي بيعت ڪئي. (بخاري، ڪتاب الاحڪام)", "bait.007": "حجة الاسلام امام غزاليؒ فرمائين ٿا ته انبياءِ ڪرام عليهم السلام کان سواءِ ڪو به ظاهري ۽ باطني بيمارين کان خالي ناهي. تنهنڪري انهن بيمارين جي ازالي لاءِ صوفين سان گڏ طريقت ۾ داخل ٿيڻ ضروري آهي. جيئن علمِ طب ۾ اها ڳالهه طئي آهي ته طب جا ڪتاب پڙهڻ باوجود ڪو به پاڻمرادو پنهنجو علاج نٿو ڪري سگهي، بلڪه ان لاءِ ڪو طبيب گهرجي. بلڪل ائين ئي دل ۽ نفس جي بيمارين جو علاج به پاڻمرادو نٿو ڪري سگهجي، انهن لاءِ به هڪ مرشدِ ڪامل جي ضرورت آهي.", "bait.008": "سيدنا عبدالقادر عيسيٰؒ شاذلي فرمائين ٿا ته نبي ڪريم ﷺ جا صحابهٔ ڪرامؓ به رڳو قرآن پڙهڻ سان پنهنجن نفسن جو علاج نٿي ڪري سگهيا، اهي به حاذقِ ڪونين ﷺ جي شفاخاني سان وابسته هئا ۽ آپ ﷺ سندن تزڪيهٔ نفس ۽ تصفيهٔ قلب فرمائيندا هئا. (حقائق عن التصوف)", "bait.009": "اسان جا ڏاڏا مرشد شمس الڪونين فاتحِ قاديانيت خواجه محمد عبدالخالقؒ فرمائين ٿا: بيعت لفظ بيع مان نڪتو آهي، جنهن جي معنيٰ وڪامجڻ آهي. جنهن وقت مريد بيعت ٿئي ٿو ته پنهنجا سمورا ارادا پير جي حوالي ڪري ڇڏي ٿو. جيڪا شيءِ وڪڻي ڇڏجي ته ٻنهي ڌرين جي رضامنديءَ کان سواءِ اها واپس نٿي وٺي سگهجي، ته پوءِ اها ٻئي هنڌ ڪيئن وڪڻي سگهجي ٿي. (لمعاتِ ڪمالاتِ قادريه)", "bait.010": "بيعتِ طريقت جو مقصد", "bait.011": "امامِ رباني مجدد الفِ ثانيؒ فرمائين ٿا ته شريعت جا ٽي جزا علم، عمل ۽ اخلاص آهن. ۽ طريقت شريعت جي ٽئين جزي يعني اخلاص حاصل ڪرڻ جو ذريعو آهي. پوءِ طريقت شريعت کان ڪا الڳ شيءِ ناهي، بلڪه شريعت کي ڪامل ڪرڻ ۾ شريعت جي خادم آهي.", "bait.012": "پوءِ بيعت جو اصل مقصد اخلاص يعني الله جي رضا حاصل ڪرڻ آهي. جنهن جو ذريعو شريعت جي احڪامن ۽ سنتِ نبوي ﷺ تي پوريءَ طرح هلڻ، خدا تعاليٰ جي مرضيءَ تي راضي رهڻ، لالچ نه ڪرڻ، عبادت ۾ دل کي حاضر رکڻ، دين جا ڪم اخلاص سان ڪرڻ، ڪنهن کي به حقير نه سمجهڻ، خود پسنديءَ کان بچڻ، ڪاوڙ کي ضبط ڪرڻ ۽ ذڪر ۽ فڪر ۾ مشغول رهڻ آهي. اهڙا اخلاق اختيار ڪرڻ کي سلوڪ چئبو آهي.", "bait.013": "ڄاڻڻ گهرجي ته هن ۾ نه ڪشف ۽ ڪرامتون ضروري آهن، نه دنياوي ڪمن ۾ ڪاميابيءَ جو واعدو آهي، نه ئي ڦوڪ ڦاڪ سان بيماري ختم ٿيڻ جي دعويٰ، نه ئي ايندڙ واقعن جي خبر، نه ئي تصرف لازم آهن ته پير جي توجه سان مريد جي اصلاح پاڻمرادو ٿي ويندي، نه اهڙين باطني ڪيفيتن پيدا ٿيڻ جي ڪا مدت آهي ته هر وقت يا گهٽ ۾ گهٽ عبادت وقت لذت سان سرشار ۽ مست رهي ۽ عبادت ۾ وسوسا ئي نه اچن، نه ذڪر ۽ شغل ۾ انوار وغيره نظر اچڻ يا ڪنهن آواز جو ٻڌڻ ضروري آهي، نه ئي سٺن خوابن جو نظر اچڻ يا الهامن جو صحيح ۽ درست هجڻ ضروري آهي.", "bait.014": "شيخِ ڪامل جون شرطون", "bait.015": "هن دور ۾ جعلسازي ۽ شعبده بازي عروج تي آهي ۽ تصوف جي حقيقي چهري کي بگاڙي پيش ڪيو پيو وڃي. تنهنڪري ضمني طور شيخِ ڪامل جون پنج شرطون بيان ڪجن ٿيون ته جيئن سالڪانِ طريقت اصل ۽ نقل جي سڃاڻپ پاڻ ڪري پاڻ کي گمراهيءَ کان بچائي سگهن.", "bait.016": "اعليٰ حضرت امام احمد رضا خان بريلويؒ پيرِ ڪامل جي شرطن بابت فرمائين ٿا ته", "bait.017": "<b class=\"az-n\">۱. عقيدو:</b> پير مذهبِ اهلِ سنت والجماعت جو صحيح العقيدي هجي، ڇو ته بدمذهب گمراهه جو سلسلو شيطان تائين پهچندو نه ڪي رسول الله ﷺ تائين. (هن دور ۾ جيڪڏهن ڪنهن پير جو عقيدو حضرات شيخين يعني حضرت صديق ۽ عمر رضي الله عنهما جي افضليت جي خلاف هجي يا سيدنا امير معاويهؓ بابت سٺي راءِ نه رکندو هجي ته سني مريد کي گهرجي ته اهڙي پير جي بيعت فوراً ٽوڙي ڪنهن صحيح العقيدي شيخ سان بيعت ڪري).", "bait.018": "عقيدي جي درستيءَ بابت قيومِ زمان مرزا مظهر جانِ جانان شهيدؒ دهلوي فرمائين ٿا: اهلِ بيتِ اطهار سان محبت جو اظهار ۽ صحابهٔ ڪرامؓ جي هڪجهڙي تعظيم لازم آهي. اهو ئي صراطِ مستقيم آهي جيڪو قيامت جي ڏينهن پل صراط جي صورت ۾ ظاهر ٿيندو، جيڪو دنيا ۾ هن راهه کان منحرف نه ٿيندو اهو قيامت جي ڏينهن ان تان استقامت سان گذري ويندو. (مقاماتِ مظهري)", "bait.019": "<b class=\"az-n\">۲. علم:</b> ايترو علم شرط آهي جو ڪنهن مدد کان سواءِ پنهنجي ضرورت جا مسئلا ڪتاب مان ڪڍي سگهي. مطالعو ڪري ۽ ماڻهن کان ٻڌي ٻڌي به عالم بڻجي سگهي ٿو. فارغ التحصيل هجڻ جي سند نه شرط آهي ۽ نه ڪافي، بلڪه علم هجڻ گهرجي. شريعت جي احڪامن، امر ۽ نهي، حلال ۽ حرام، فرض ۽ واجب، سنت ۽ مستحب ۽ ڪفر ۽ اسلام يعني علمِ فقه کان باخبر هجي. ۽ عربي عبارت چڱيءَ طرح پڙهي سگهندو هجي.", "bait.020": "اسان جا ڏاڏا مرشد شمس الڪونين خواجه محمد عبدالخالق شمس العرفاني نقشبنديؒ فرمائين ٿا", "bait.021": "<b class=\"az-n\">۳. عمل:</b> پنهنجي علم تي عمل ڪندڙ هجي. ڪو به فرض، سنت يا مستحب ان کان قضا نه ٿئي، ايتري قدر جو ڦڻي ۽ مسواڪ جو استعمال ڪندو هجي، نماز باجماعت پڙهي ۽ جمعو نه ڇڏي. شريعت تي مضبوطيءَ سان عمل پيرا هجي ۽ متابعتِ مصطفيٰ ﷺ ۾ ڪوتاهي نه ڪري.", "bait.022": "<b class=\"az-n\">۴. اخلاص:</b> شمس الڪونين خواجه عبدالخالقؒ فرمائين ٿا ته پير جو هر عمل الله جي رضا لاءِ هجي.", "bait.023": "<b class=\"az-n\">۵. سلسلو ۽ خلافت:</b> پير جو سلسلهٔ طريقت صحيح هجي، يعني هو ڪنهن پير جو مريد هجي ۽ خلافت يافته هجي ته جيئن ان جو هٿ دست بدست رسول الله ﷺ تائين پهچي. جيڪو شخص خلافت کان سواءِ بيعت ڪري ٿو، اهلِ طريقت ان کي زنديق سمجهن ٿا ۽ اهو گمراهه آهي. ۽ ڪي ماڻهو مريد ٿيڻ کان سواءِ رڳو پيرزادا هجڻ جي گمان ۾ پنهنجي ابن ڏاڏن جي مزار تي سجاده نشين بڻجي ويهي رهن ٿا. يا سلسلو ئي اهڙو هجي جيڪو ڪٽيو ويو هجي ۽ ان ۾ فيض نه رکيو ويو هجي، ماڻهو لالچ خاطر ان سلسلي ۾ خلافت ڏيندا اچن ٿا، يا سلسلو ته صحيح هو پر وچ ۾ ڪو اهڙو شخص آيو جيڪو پيريءَ جي لائق نه هو، ان کان جيڪا شاخ هلي اها وچ ۾ ئي ڪٽيل آهي. انهن سڀني صورتن ۾ اهڙي بيعت سان هرگز رسول الله ﷺ جي دستِ مبارڪ تائين نه پهچبو ۽ فيض حاصل نه ٿيندو، ڇو ته ڏاند مان کير يا بانجهه مان ٻار نه ٿيندو آهي.", "bait.024": "شيخِ ڪامل جون بنيادي صفتون", "bait.025": "ڄاڻڻ گهرجي ته پيرِ ڪامل ۾ هيٺيون پنج صفتون ضرور هجڻ گهرجن.", "bait.026": "سلطان العارفين شيخ بايزيدؒ بسطامي فرمائين ٿا:", "bait.027": "<b class=\"az-n\">۱.</b> پير سٺن اخلاقن وارو هجي.", "bait.028": "<b class=\"az-n\">۲.</b> سخي هجي.", "bait.029": "<b class=\"az-n\">۳.</b> عاجز هجي.", "bait.030": "اسان جا شمس الڪونين خواجه عبدالخالقؒ فرمائين ٿا:", "bait.031": "<b class=\"az-n\">۴.</b> پير خلقِ عظيم رکندو هجي ته جيئن مريد جون مشڪلاتون آسانيءَ سان حل ٿين.", "bait.032": "<b class=\"az-n\">۵.</b> پير بيعت ڪرڻ وقت جسم جي هر وار مان اسمِ ذات جو ذڪر جاري ڪرائي ڇڏي.", "mamulat.001": "ختمِ خواجگانِ نقشبنديه", "mamulat.002": "جاري ڪيل: مظهرِ جمالِ مصطفائي خواجهٔ خواجگان، حاميءِ بيوگان، دستگيرِ يتاميٰ، فاتحِ قاديانيت، قطب الاقطاب، شمس الڪونين ابوسعد محمد عبدالخالق نقشبنديؒ", "mamulat.003": "نوٽ: هر ورد کان اڳ هڪ ڀيرو بسم الله شريف ضرور پڙهو.", "mamulat.004": "(مان الله کان بخشش گهران ٿو، جنهن کان سواءِ ڪو معبود ناهي، اهو زنده ۽ قائم رکڻ وارو آهي، ۽ مان ان ڏانهن ئي رجوع ڪريان ٿو).", "mamulat.005": "سورة الفاتحه <span class=\"kk-c\">۷ ڀيرا</span>", "mamulat.006": "درودِ خالقيه", "mamulat.007": "(اي الله! پنهنجي سموري علم جي برابر درود موڪل اسان جي سردار حضرت محمد ﷺ تي ۽ اسان جي سردار حضرت محمد ﷺ جي آل ۽ اصحابن تي).", "mamulat.008": "سورة الم نشرح <span class=\"kk-c\">۷۹ ڀيرا</span>", "mamulat.009": "سورة الاخلاص بسم الله شريف سميت <span class=\"kk-c\">۱۰۰۰ ڀيرا</span>", "mamulat.010": "سورة الفاتحه <span class=\"kk-c\">۷ ڀيرا</span>", "mamulat.011": "هيٺيان سمورا ڪلما سؤ سؤ ڀيرا پڙهو:", "mamulat.012": "درودِ خالقيه", "mamulat.013": "(گناهن کان بچڻ جي طاقت ۽ نيڪي ڪرڻ جي قوت الله جي طرفان آهي)", "mamulat.014": "(تو کان سواءِ ڪو معبود ناهي، تون پاڪ آهين (ظلم ڪرڻ کان)، بيشڪ مان ئي ظالمن مان آهيان، يعني پاڻ تي ظلم ڪري ويهان ٿو).", "mamulat.015": "(يا حي ۽ قيوم، پنهنجي رحمت جي صدقي مدد فرماءِ، اي مدد گهرندڙن جا مددگار)", "mamulat.016": "(اي عزت وارا! مون کي مخلوق جي نظر ۾ عزت وارو بڻاءِ)", "mamulat.017": "(اي حاجتون پوريون ڪرڻ وارا)", "mamulat.018": "(اي درجا بلند ڪرڻ وارا)", "mamulat.019": "(اي بلائون پري ڪرڻ وارا)", "mamulat.020": "(اي مشڪلاتون کولڻ وارا)", "mamulat.021": "(اي بيمارين کان شفا ڏيڻ وارا)", "mamulat.022": "(اي دعائون قبول ڪرڻ وارا)", "mamulat.023": "(اي مشڪلاتون حل ڪرڻ وارا)", "mamulat.024": "(اي سبب پيدا ڪرڻ وارا)", "mamulat.025": "(اي بي نياز ۽ غني بڻائي ڇڏڻ وارا)", "mamulat.026": "(اي هر شيءِ کان بي نياز ۽ بي پرواهه)", "mamulat.027": "(اي گهڻائيءَ سان پيدا ڪرڻ وارا)", "mamulat.028": "(اي رزق ڏيڻ ۽ گهڻو عطا ڪرڻ وارا)", "mamulat.029": "(اي انعام ۽ نعمتون عطا ڪرڻ وارا)", "mamulat.030": "(اي بي نياز! پاڻ کان سواءِ ٻين کان بي نياز ڪري ڇڏڻ وارا)", "mamulat.031": "(اي بي حد محبت ڪرڻ وارا)", "mamulat.032": "(اي هر ڪنهن تي بي حد رحم ڪرڻ وارا)", "mamulat.033": "(اي پنهنجي خاص ۽ چاهيندڙن تي تمام گهڻو مهربان)", "mamulat.034": "(اي تمام گهڻو ڪرم ڪرڻ وارا)", "mamulat.035": "(اي بخشڻ وارا)", "mamulat.036": "(اي تمام گهڻو درگذر ۽ پردو پوشي ڪرڻ وارا)", "mamulat.037": "(اي مشڪل ڪشا ۽ آسانين جو دروازو کولڻ وارا)", "mamulat.038": "(اي سڀ ڪجهه عطا ڪرڻ وارا)", "mamulat.039": "(اي عزت ڏيڻ وارا)", "mamulat.040": "(اي بلندي عطا ڪرڻ وارا)", "mamulat.041": "(اي روزي ڪشادي ڪرڻ وارا)", "mamulat.042": "(اي بي عيب ذات! سلامتي عطا ڪرڻ وارا)", "mamulat.043": "(اي حقيقي ڪارساز)", "mamulat.044": "(اي نگهبان! مخلوق جي نگهباني ڪرڻ وارا)", "mamulat.045": "(اي سڀني جهانن جا پروردگار)", "mamulat.046": "(اي سڀني جهانن جا حقيقي پالڻهار)", "mamulat.047": "(اي سڀني جهانن جا حقيقي رب)", "mamulat.048": "(پنهنجي رحمت جي صدقي! اي سڀ کان وڌيڪ رحم ڪرڻ وارا)", "mamulat.049": "هاڻي ننڍو ختم شريف پڙهو:", "mamulat.050": "(اي الله! مان تو کان مغفرت گهران ٿو)", "mamulat.051": "(اي الله! اي منهنجا رب! مان هر گناهه کان معافي گهران ٿو ۽ تنهنجي طرف رجوع ڪريان ٿو)", "mamulat.052": "سورة الفاتحه <span class=\"kk-c\">۷ ڀيرا</span>", "mamulat.053": "درودِ خالقيه <span class=\"kk-c\">۱۱ ڀيرا</span>", "mamulat.054": "حضور نبي ڪريم ﷺ جي طفيل، سمورن انبياءِ ڪرام عليهم السلام، خلفاءِ راشدين، اهلِ بيتِ اطهار، صحابهٔ ڪرام رضي الله عنهم ۽ پيرانِ عظام کي ايصالِ ثواب ڪريو.", "shajra.001": "شجرو طريقت", "shajra.002": "چئني سلسلن مان خلافت هوندي به اسان جي مرشدن سلسلهٔ عاليه نقشبنديه مجدديه جي ترويج ڪئي. تنهنڪري سلسلهٔ عاليه جي بزرگن جا نالا عام ماڻهن جي آگاهيءَ لاءِ تبرڪ طور پيش ڪيا پيا وڃن.", "shajra.003": "رحمۃ للعالمین، خاتم النبیین، سید المرسلین، حضرت محمد مصطفیٰ ﷺ<small>وصال 11ھ ۔ مدفن گنبدِ خضريٰ</small>", "shajra.004": "یارِ غار و مزار، افضل البشر بعد الانبیاء بالتحقیق، سیدنا ابوبکر صدیقؓ<small>13ھ ۔ گنبدِ خضريٰ، مدينه منوره</small>", "shajra.005": "پاڪباز صحابي، صاحبِ رسول الله ﷺ، حضرت سیدنا سلمان فارسیؓ<small>33ھ ۔ مدائن، عراق</small>", "shajra.006": "حضرت سیدنا امام قاسمؒ بن سیدنا محمدؒ بن سیدنا ابوبکر صدیقؓ<small>106ھ ۔ مدينه منوره</small>", "shajra.007": "امام الشریعت، ہادیِ طریقت حضرت سیدنا امام جعفر صادقؒ<small>148ھ ۔ جنت البقيع، قبهٔ اهلِ بيت</small>", "shajra.008": "سلطان العارفین، غوثِ زمانی، حضرت شیخ بایزید بسطامیؒ<small>261ھ ۔ بسطام، ايران</small>", "shajra.009": "قطبِ ربانی، غوثِ زماں، خواجہ ابوالحسن خرقانیؒ<small>425ھ ۔ خرقان، بسطام ويجهو، ايران</small>", "shajra.010": "عارفِ ربانی، قطبِ زمانی، حضرت شیخ ابوالقاسم گرگانیؒ<small>450ھ ۔ گرگان، ايران</small>", "shajra.011": "قطبِ صمدانی، حضرت شیخ بوعلی فارمدیؒ<small>477ھ ۔ فارمد، طوس ويجهو، خراسان، ايران</small>", "shajra.012": "رئیس الطریقت، غوثِ زماں، امامِ ربانی، خواجہ یوسف ہمدانیؒ<small>535ھ ۔ مرو، ايران</small>", "shajra.013": "امام الطریقت خواجۂ جہاں خواجہ عبدالخالق غجدوانیؒ<small>575ھ ۔ غجدوان، بخارا ويجهو، ازبڪستان</small>", "shajra.014": "نورِ خدا، واقفِ معارفِ پیغمبری، خواجہ عارف ریوگریؒ<small>616ھ ۔ ريوگر، بخارا ويجهو، ازبڪستان</small>", "shajra.015": "خواجۂ خواجگاں، قطبِ جہاں، حضرت خواجہ محمود انجیر فغنویؒ<small>715ھ ۔ انجير فغنه، بخارا ويجهو</small>", "shajra.016": "قطبِ زماں، مجددِ دوراں، حضرت خواجہ عزیزان علی رامیتنیؒ<small>718ھ ۔ خوارزم، ازبڪستان</small>", "shajra.017": "بابِ الطریقت، آفتابِ حقیقت حضرت خواجہ بابا محمد سماسیؒ<small>755ھ ۔ سماس، بخارا ويجهو</small>", "shajra.018": "عارفِ باکمال، صاحبِ وجد و حال، شمس الدین سید امیر کلالؒ<small>772ھ ۔ سوخار، بخارا</small>", "shajra.019": "امام الطریقت پیرِ پیراں خواجۂ خواجگاں خواجہ بہاؤالدین نقشبندؒ<small>791ھ ۔ قصرِ عارفان، بخارا</small>", "shajra.020": "امام العارفین، قطبِ ارشاد حضرت خواجہ علاؤالدین عطارؒ<small>802ھ ۔ چغانيان، بخارا ويجهو</small>", "shajra.021": "شمس الہدایت، عارفِ ربانی، حضرت مولانا محمد یعقوب چرخیؒ<small>851ھ ۔ ماوراء النهر، تاجڪستان</small>", "shajra.022": "مرشدِ عارف، خواجہ ناصرالدین عبیداللہ احرارؒ<small>895ھ ۔ سمرقند، ازبڪستان</small>", "shajra.023": "فیضِ الٰہی، یکتائے زمانہ، حضرت مولانا خواجہ محمد زاہد وخشیؒ<small>936ھ ۔ وخش، بلخ</small>", "shajra.024": "مستِ عشق، حضرت مولانا خواجہ درویش محمد امکنگیؒ<small>970ھ ۔ ماوراء النهر</small>", "shajra.025": "مرکزِ دائرۂ قطبیت، دربانِ رسول مولانا شاہ محمد خواجگی امکنگیؒ<small>1008ھ ۔ امڪنه، بخارا</small>", "shajra.026": "فخرِ اسلام، نقشبندِ وقت، قطبِ زماں، خواجہ محمد باقی باللہ بیرنگؒ<small>1012ھ ۔ دهلي، انڊيا</small>", "shajra.027": "قیومِ اوّل، امامِ ربانی، مجدد الفِ ثانی، شیخ احمد فاروقی سرہندیؒ<small>1034ھ ۔ سرهند، انڊيا</small>", "shajra.028": "قیومِ ثانی، عروۃ الوثقیٰ خواجہ محمد معصومؒ<small>مجدد الفِ ثانيؒ جا شهزادا ۔ 1079ھ ۔ سرهند شريف</small>", "shajra.029": "قاطعِ بدعت، محتسبِ اُمت شیخ سیف الدینؒ<small>قيومِ ثانيؒ جا شهزادا ۔ 1096ھ ۔ سرهند شريف</small>", "shajra.030": "کشف الدجیٰ حضرت حافظ محمد محسنؒ<small>خواجه محمد معصومؒ جا خليفا ۔ 1147ھ ۔ دهلي</small>", "shajra.031": "حضرت سید نور محمد بدایونیؒ<small>شيخ سيف الدينؒ جا خليفا ۔ 1135ھ ۔ دهلي</small>", "shajra.032": "قطبِ زماں خواجہ محمد عابد سنامیؒ<small>عبدالاحد سرهندي مجددي قادريؒ جا خليفا ۔ 1160ھ ۔ دهلي</small>", "shajra.033": "قیومِ زماں، قطبِ جہاں، شمس الدین حبیب اللہ مرزا مظہر جانِ جاناں شہیدؒ<small>1195ھ ۔ دهلي</small>", "shajra.034": "مجددِ دوراں، قیومِ زماں حضرت شاہ عبداللہ غلام علی دہلویؒ<small>1240ھ ۔ دهلي</small>", "shajra.035": "شیخ المشائخ، قیومِ زماں، حضرت شاہ ابوسعید فاروقی مجددیؒ<small>1250ھ ۔ دهلي</small>", "shajra.036": "شمس الاولیاء، حضرت مولانا بابا محمد شریف قندھاریؒ<small>1260ھ ۔ سرهند شريف</small>", "shajra.037": "سلطان الفقراء، حضرت حاجی محمود جالندھریؒ<small>1306ھ ۔ جالنڌر شريف، انڊيا</small>", "shajra.038": "شمس العرفان خواجہ قادر بخشؒ<small>1306ھ ۔ ڪوٽ عبدالخالق جهانخيل، ضلعو هوشيارپور، انڊيا</small>", "shajra.039": "شمس الکونین خواجہ محمد عبدالخالق نقشبندیؒ<small>1931ع ۔ ڪوٽ عبدالخالق جهانخيل، ضلعو هوشيارپور، انڊيا</small>", "shajra.040": "شمس العارفین سائیں عبدالرزاق خالقی نقشبندیؒ<small>1982ع ۔ ديپالپور شريف، ضلعو اوڪاڙه</small>", "shajra.041": "امام الذاکرین حضور سائیں محمد عظیم اللہ رزاقی نقشبندیؒ<small>2013ع ۔ عظيم نگر شريف، ضلعو بهاولنگر</small>", "shajra.042": "شجره شريف (منظوم)", "shajra.043": "هن شجرهٔ طيبه کي تمام ادب سان باوضو پڙهڻ جي سخت تاڪيد آهي. پڙهندي وقت دل حاضر ڪري پنهنجي سبق ڏانهن ڌيان ڏيو، پنهنجي روحاني نسبت درست رکي پيرانِ عظام کان فيض طلب ڪريو. هي شجرهٔ طيبه حضور سيد عالم محمد مصطفيٰ ﷺ جو محبوب ۽ مقبول آهي. نبي ڪريم رؤف رحيم ﷺ پنهنجي هن غلامن جي غلام جي عاجزي قبول فرمائي خواب ۾ فقير کي آگاهه فرمايو آهي ته جيڪو شخص هن شجرهٔ طيبه کي خلوصِ نيت سان پڙهندو، ان جي ڪهڙي به مشڪل هجي، ان شاء الله العزيز خواجگانِ نقشبنديه جي طفيل ضرور حل ٿيندي. شجره شريف پڙهي حضور نبي ڪريم ﷺ جي وسيلي سان عرض ڪريو ۽ محلل المشڪلات، مسبب الاسباب، اله العالمين کان مشڪلاتن جي حل لاءِ دعا گهرو.", "shajra.044": "محمد مصطفيٰ ﷺ جي واسطي منهنجي دستگيري ڪر.", "shajra.045": "سڀني انبياءَ جي آل ۽ اصحابن جي واسطي.", "shajra.046": "يا الاهي! پنهنجو درد منهنجي دل جو نصيب بڻاءِ،", "shajra.047": "صاف دل ابوبڪر صديقِ اڪبرؓ جي واسطي.", "shajra.048": "اي خداوند! مون کي پنهنجي عشق ۾ ڪباب بڻاءِ،", "shajra.049": "حيا واري صاحب سلمان فارسيؓ جي واسطي.", "shajra.050": "الله کان سواءِ منهنجا سڀ خيال دل مان پري ٿي وڃن،", "shajra.051": "هدايت جي پير امام قاسمؒ جي واسطي.", "shajra.052": "يا الاهي! ڪافر نفس جي شر کان بچائي وٺ،", "shajra.053": "پرهيزگارن جي امام جعفر صادقؒ جي واسطي.", "shajra.054": "يا الاهي! مون کي شيطان جي مڪر کان آگاهه ڪر،", "shajra.055": "رهنما بايزيدؒ جي واسطي.", "shajra.056": "ڪو به پل تنهنجي ياد کان غافل نه ٿيان،", "shajra.057": "اولياءَ جي تاج خواجه ابوالحسنؒ جي واسطي.", "shajra.058": "اي رب! مون کي پنهنجي ذاتِ مطلق ۾ فنا ڪر،", "shajra.059": "صاحبِ لوا شاهه ابوالقاسمؒ جي واسطي.", "shajra.060": "اي منهنجا رب! مون کي عين مطلق ذات کان جدا نه ڪر،", "shajra.061": "باوفا پير ۽ مرشد بوعليؒ جي واسطي.", "shajra.062": "دل مان غير جي غيريت ڪڍي ڇڏ ۽ هميشه جي حضوري عطا ڪر،", "shajra.063": "مقبول الدعا شاهه خواجه يوسفؒ جي واسطي.", "shajra.064": "اي رب! منهنجي روح نقل مان نڪري اصل ۾ شامل ٿي وڃي،", "shajra.065": "خطائن جي شفاعت ڪندڙ عبدالخالق غجدوانيؒ جي واسطي.", "shajra.066": "نفس جي معرفت ڏي ته جيئن اصل کي سڃاڻي وٺان،", "shajra.067": "نورِ خدا محمد عارفؒ جي واسطي.", "shajra.068": "عاشقن جي دائري کي معشوق سان ملائي ڇڏ،", "shajra.069": "خواجه محمود انجير فغنويؒ جي واسطي.", "shajra.070": "هي غريب هر دم تنهنجي وصال ۾ آرام ڪري،", "shajra.071": "شاهه عزيزان عليؒ جي واسطي.", "shajra.072": "پنهنجي رحمت جي نظر سان منهنجون سڀ خطائون معاف ڪر،", "shajra.073": "باادب خواجه بابا محمدؒ جي واسطي.", "shajra.074": "يا الاهي! مون کي امتِ احمد ۾ شمار ڪري وٺ،", "shajra.075": "رضا واري سيد مير ڪلالؒ جي واسطي.", "shajra.076": "مون کي شريعت ۽ طريقت تي ثابت قدم رک،", "shajra.077": "پيشوا شاهه بهاؤالدين خواجهؒ جي واسطي.", "shajra.078": "صراطِ مستقيم تي هميشه جي استقامت عطا ڪر،", "shajra.079": "روشنيءَ وارا شاهه علاؤالدين عطارؒ جي واسطي.", "shajra.080": "اي خداوند! مون کي پير جي محبت عطا ڪر،", "shajra.081": "رياڪاريءَ کان پاڪ خواجه يعقوب چرخيؒ جي واسطي.", "shajra.082": "اي رب! مون کي پيرانِ ڪرام جي نظر ۾ مقبول ڪر،", "shajra.083": "سخاوت وارا عبيدالله احرارؒ جي واسطي.", "shajra.084": "منهنجي پير جو عشق منهنجي دل ۾ وسائي ڇڏ،", "shajra.085": "برگزيده خواجه محمد زاهدؒ جي واسطي.", "shajra.086": "اي رب! پيرن جي نصيحت جو هر دم مون کي خيال رهي،", "shajra.087": "دلربا خواجه درويش محمدؒ جي واسطي.", "shajra.088": "اي ڪريم خداوند! منهنجي دل ۾ توڪل عطا ڪر،", "shajra.089": "بلند مرتبي وارا شاهه محمد خواجگيؒ جي واسطي.", "shajra.090": "مون کي دنيا ۾ ڪڏهن به غمگين نه ڪجانءِ،", "shajra.091": "بقا وارا محمد باقي باللهؒ جي واسطي.", "shajra.092": "اي منهنجا الاهه! مون کي پاڻ کان سواءِ ڪنهن غير جو محتاج نه ڪر،", "shajra.093": "بدرالدجيٰ مجدد صاحبؒ جي واسطي.", "shajra.094": "جڏهن نزع جو وقت هجي ته تنهنجو ڪلمو منهنجي زبان تي هجي،", "shajra.095": "حضرت خواجه معصومؒ جي واسطي.", "shajra.096": "ان وقت مون کي شيطان جي شر کان بچائي وٺجانءِ،", "shajra.097": "مصطفيٰ ﷺ جي عاشق شيخ سيف الدينؒ جي واسطي.", "shajra.098": "پنهنجي فضل سان مون کي سڪرات ۾ ڇوٽڪارو ڏجانءِ،", "shajra.099": "ڪهف الوريٰ محمد عابدؒ جي واسطي.", "shajra.100": "الاهي! تنهنجي فضل سان منهنجي قبر روشن هجي،", "shajra.101": "ڪشف الدجيٰ شاهه محمد محسنؒ جي واسطي.", "shajra.102": "نه قبر جي سختي هجي ۽ نه فرشتي جي ڪا پريشاني،", "shajra.103": "سهڻي چهري واري سيد نور محمدؒ جي واسطي.", "shajra.104": "جڏهن پل صراط تي هلان ته لنگهڻ آسان هجي،", "shajra.105": "اسان جي جان خواجه مرزا جانِ جاناںؒ جي واسطي.", "shajra.106": "اي رب! جنهن وقت تنهنجو سج تيز هجي ته امن ڏجانءِ،", "shajra.107": "شمس الضحيٰ غلام شاهه عليؒ جي واسطي.", "shajra.108": "يا الاهي! ترازيءَ ۾ نيڪيءَ جو پلڙو ڳرو هجي،", "shajra.109": "برگزيده ٻانهن جي رهنما ابوسعيدؒ جي واسطي.", "shajra.110": "اي جهان جا خالق! ان وقت ڪا پريشاني نه هجي،", "shajra.111": "جان قربان ڪندڙ محمد شريفؒ جي واسطي.", "shajra.112": "اي علم وارا خداوند! منهنجو گذر عاشقن ۾ هجي،", "shajra.113": "دل کوليندڙ حاجي محمود حافظؒ جي واسطي.", "shajra.114": "اي رب! قيامت جي ڏينهن مان پير جي ڇانوَ هيٺ رهان،", "shajra.115": "هما جي ڇانوَ جهڙا خواجه قادر بخشؒ جي واسطي.", "shajra.116": "جدائيءَ جي تپ سان دل ۾ درد آهي، ان جي دوا ڪري ڏي،", "shajra.117": "سڙيل دل جي دوا شمس العرفانؒ جي واسطي.", "shajra.118": "اي منهنجا رب! محبوب جو وصال هر دم منهنجي نصيب ۾ رهي،", "shajra.119": "بلند ثنا وارا سڀني خواجگان جا خواجه جي واسطي.", "shajra.120": "مان غريب حال آهيان، اي رب! رحم جي نظر ڪر،", "shajra.121": "شانِ مصطفيٰ ﷺ جا مظهر محبوب مرشد جي واسطي.", "shajra.122": "يعني منهنجي جان جو قبلو، عالم جي پناهه وارا خواجه،", "shajra.123": "پيشوا شمس الڪونين عبدالخالقؒ جي واسطي.", "shajra.124": "اي منهنجا الاهه! مون کي دين ۽ دنيا ۾ سرخرو ڪر،", "shajra.125": "منهنجي پياري پيشوا سائیں خواجهؒ جي واسطي.", "shajra.126": "غوثِ دوران، قطبِ عالم، روشن ضمير مرشد،", "shajra.127": "اولياءَ جي امام سائیں عبدالرزاقؒ جي واسطي.", "shajra.128": "اي منهنجا ڪريم رب! منهنجي اميد جي جهولي ڀري ڇڏ،", "shajra.129": "الله جي ڇانوَ جهڙي صورت واري پيرِ ڪامل جي واسطي.", "shajra.130": "منهنجي دل ۽ نظر کي ايمان جي نور سان سينگار،", "shajra.131": "نورِ خدا شاهه محمد عظيم اللهؒ جي واسطي.", "shajra.132": "تو کان سواءِ ٻيو ڪير آهي؟ مان دل جو درد ڪنهن کي چوان؟", "shajra.133": "هر مراد لاءِ تون ئي حاجت پوري ڪندڙ آهين.", "shajra.134": "اي خدا! سوين ڏکيائين جو سامنو آهي،", "shajra.135": "پنهنجي شانِ ڪبريائيءَ جي واسطي انهن کي آسان ڪري ڇڏ.", "shajra.136": "جيتوڻيڪ مان برو آهيان پر تنهنجو آهيان، اي منهنجا عزّ و جلّ،", "shajra.137": "مون بي سهارو لاءِ تنهنجي رحمت گهرجي.", "shajra.138": "يا الاهي! منهنجي اولاد کي نصيب وارو ڪر،", "shajra.139": "انبياءَ ۽ اولياءَ جي سخا ۽ عطا جي واسطي.", "shajra.140": "دوستن ۽ عزيزن مٽن کي محبت عطا ڪر،", "shajra.141": "پيشوا نبي ﷺ جي آل ۽ حرمين جي واسطي.", "shajra.142": "يا الاهي! پنهنجي گنهگار ٻانهي جي دعا قبول ڪري وٺ،", "shajra.143": "قيامت جي ڏينهن شفاعت ڪندڙ جناب ﷺ جي واسطي.", "azkar.001": "مسنون ذڪر", "azkar.002": "فجر ۽ مغرب جي نماز کان پوءِ مسنون اذڪار", "azkar.003": "<p class=\"kk-ar\" lang=\"ar\">وَسَبِّحُوْهُ بُكْرَةً وَّاَصِيْلًا</p><p class=\"kk-ur\">۽ صبح شام ان جي تسبيح ڪندا ڪريو. (سورة احزاب: ۴۲)</p>", "azkar.004": "نوٽ: اسان جا امام رباني مجدد الفِ ثانيؒ هميشه صبح شام جا مسنون اذڪار پڙهندا هئا.", "azkar.005": "(الله تعاليٰ کان سواءِ ڪو معبود ناهي، هو اڪيلو آهي، ان جو ڪو شريڪ ناهي، ان جي ئي بادشاهي آهي ۽ ان جي ئي تعريف آهي ۽ هو هر شيءِ تي قادر آهي).", "azkar.006": "اي الله! مون کي دوزخ کان نجات عطا فرماءِ.", "azkar.007": "مون لاءِ الله ڪافي آهي، ان کان سواءِ ڪو معبود ناهي، مون ان تي ئي ڀروسو ڪيو ۽ هو عرشِ عظيم جو رب آهي.", "azkar.008": "مان ان ذات تي ڀروسو رکان ٿو جيڪا زنده آهي، جنهن کي موت ناهي.", "azkar.009": "(صحيح مسلم)", "azkar.010": "۶. سورة الاخلاص ۽ معوذتين تسميه سميت <span class=\"kk-c\">۳ ڀيرا</span>", "azkar.011": "(ابوداؤد)", "azkar.012": "مان الله تعاليٰ جي رب هجڻ، اسلام جي دين هجڻ ۽ اسان جي سردار حضرت محمد ﷺ جي نبي ۽ رسول هجڻ تي راضي ٿيس.", "azkar.013": "(جامع ترمذي)", "azkar.014": "الله تعاليٰ جي نالي سان، جنهن جي نالي جي برڪت سان زمين ۽ آسمان جي ڪا به شيءِ نقصان نٿي پهچائي سگهي، ۽ هو ٻڌندڙ ڄاڻندڙ آهي.", "azkar.015": "(ترمذي)", "azkar.016": "اي الله! منهنجي بدن ۾ عافيت ڏي، اي الله! منهنجي ٻڌڻ ۾ عافيت ڏي، اي الله! منهنجي ڏسڻ ۾ عافيت ڏي، تو کان سواءِ ڪو معبود ناهي.", "azkar.017": "(صحيح مسلم)", "azkar.018": "مان الله جي پورن ۽ ڪامل ڪلمن سان مخلوق جي شر کان پناهه وٺان ٿو.", "azkar.019": "(صحيح مسلم)", "azkar.020": "پنج وقتي نماز کان پوءِ مسنون اذڪار", "azkar.021": "<p class=\"kk-ar\" lang=\"ar\">فَاِذَا قَضَيْتُمُ الصَّلٰوةَ فَاذْكُرُوا اللّٰهَ قِيٰمًا وَّقُعُوْدًا وَّعَلٰى جُنُوْبِكُمْ</p><p class=\"kk-ur\">پوءِ جڏهن توهان نماز پڙهي وٺو ته بيٺي، ويٺي ۽ پاسن ڀر ليٽي الله جو ذڪر ڪريو. (سورة النساء: ۱۰۳)</p>", "azkar.022": "<p class=\"kk-ar\" lang=\"ar\">فَسَبِّحْهُ وَاَدْبَارَ السُّجُوْدِ</p><p class=\"kk-ur\">۽ ان جي تسبيح ڪريو ۽ نمازن کان پوءِ به. (سورة ق: ۴۰)</p>", "azkar.023": "نوٽ: اسان جا امام رباني مجدد الفِ ثانيؒ هر نماز کان پوءِ مسنون دعائون پڙهندا هئا. ڪلما پڙهندي ترتيل، تجويد ۽ معنيٰ جو خيال رکو. هر ورد کان اڳ تسميه پڙهو.", "azkar.024": "اي الله! تون ئي سلامتيءَ وارو آهين ۽ تو ئي طرفان سلامتي آهي. تون تمام بابرڪت آهين، اي وڏي شان ۽ عزت وارا.", "azkar.025": "(صحيح مسلم)", "azkar.026": "۳. آيت الڪرسي", "azkar.027": "(سلسلة الاحاديث الصحيحه)", "azkar.028": "اي دلين کي ڦيرائڻ وارا! منهنجي دل کي پنهنجي دين ۽ پنهنجي اطاعت تي قائم رک.", "azkar.029": "(ترمذي)", "azkar.030": "اي اسان جا رب! اسان جي دلين کي ڏنگو نه ڪر ان کان پوءِ جو تو اسان کي هدايت ڏني، ۽ اسان کي پنهنجي طرفان رحمت عطا ڪر، بيشڪ تون تمام گهڻو عطا ڪرڻ وارو آهين.", "azkar.031": "(ابنِ ماجه) (سورة آلِ عمران: ۸)", "azkar.032": "اي الله! پنهنجي ذڪر، شڪر ۽ پنهنجي بهترين عبادت ڪرڻ ۾ منهنجي مدد فرماءِ.", "azkar.033": "(ابوداؤد)", "azkar.034": "اي زنده ۽ قائم رهڻ وارا! تو کان سواءِ ڪو معبود ناهي، مان سوال ڪريان ٿو ته منهنجي دل کي هميشه لاءِ پنهنجي نورِ معرفت سان زنده رک، اي وڏي جلال ۽ بزرگيءَ وارا! تون پاڪ آهين.", "azkar.035": "(ڪنز العمال)", "azkar.036": "۸. تسبيحِ فاطمه", "azkar.037": "سبحان الله ۳۳ ڀيرا، الحمد لله ۳۳ ڀيرا، الله اڪبر ۳۳ ڀيرا ۽ هڪ ڀيرو ڪلمهٔ توحيد.", "azkar.038": "(صحيح مسلم)", "azkar.039": "(ترمذي)", "azkar.040": "۱۰. ڪلمهٔ تمجيد", "azkar.041": "۱۱. ٽيئي قل شريف", "azkar.042": "۱۱. سورة اخلاص <span class=\"kk-c\">۱۰ ڀيرا</span>", "azkar.043": "(مسند احمد)", "azkar.044": "ننڍو ختمِ خواجگان", "azkar.045": "هيٺيون ننڍو ختمِ خواجگان فجر جي نماز ۽ عصر جي نماز کان پوءِ پڙهڻ جو معمول بڻايو.", "azkar.046": "۱. اَستغفر الله <span class=\"kk-c\">۲۶ ڀيرا</span>", "azkar.047": "۲. سورة الفاتحه <span class=\"kk-c\">۷ ڀيرا</span>", "azkar.048": "۳. درود شريف <span class=\"kk-c\">۱۱ ڀيرا</span>", "azkar.049": "نماز جون اضافي مسنون دعائون", "azkar.050": "نوٽ: عروة الوثقيٰ خواجه محمد معصوم سرهنديؒ فرمائين ٿا ته ثنا پڙهڻ کان علاوه نماز شروع ڪرڻ جون ماثور دعائون، ۽ اهڙي طرح تسبيحات کان علاوه رڪوع ۽ سجدي جون دعائون ۽ قومي ۽ جلسي جون دعائون جيڪي احاديثِ مبارڪه ۾ ذڪر ٿيل آهن، جيڪڏهن اهي تهجد ۽ ٻين نفلن ۾ پڙهو ته اهو تمام سٺو آهي، ۽ آخري قعدي ۾ درود شريف کان پوءِ قرآني دعائون يا ماثور ۽ مسنون دعائون پڙهو. جيئن صحيح بخاري ۾ حديث شريف آهي: پوءِ اها دعا گهري جيڪا کيس پسند هجي. (اذڪارِ نبويه)", "azkar.051": "الله سڀ کان وڏو آهي، تمام وڏو، ۽ الله لاءِ ئي حمد آهي، گهڻي حمد، ۽ صبح شام الله جي تسبيح ڪريان ٿو. حضرت جبير بن مطعمؓ بيان فرمائين ٿا ته هن نبي ﷺ کي هڪ نماز پڙهندي ڏٺو، آپ ﷺ نماز جي شروعات ۾ اهي ڪلما پڙهيا.", "azkar.052": "(سنن ابوداؤد)", "azkar.053": "تمام گهڻو پاڪ، انتهائي مقدس، فرشتن ۽ روح جو رب. اهي ڪلما رڪوع ۽ سجدي ۾ پڙهڻ سنت آهي. نبي ﷺ فرمايو: ٻانهو پنهنجي رب جي سڀ کان وڌيڪ ويجهو سجدي ۾ هوندو آهي، تنهنڪري سجدي ۾ گهڻي کان گهڻي دعا ڪندا ڪريو.", "azkar.054": "(صحيح مسلم)", "azkar.055": "نوٽ: اسان جا امامِ رباني مجدد الفِ ثانيؒ فارغ وقت ۾ رڪوع ۽ سجدي ۾ پنج، ست، نو يا يارهن ڀيرا تسبيحات پڙهندا هئا، ۽ فرمائيندا هئا ته شرم اچي ٿو ته طاقت هوندي به فراغت جي حالت ۾ به رڳو ٽن تسبيحن تي ئي اڪتفا ڪئي وڃي. (حضرات القدس)", "azkar.056": "اي منهنجا رب! سڀ تعريف تو لاءِ آهي، اهڙي تعريف جيڪا تمام گهڻي آهي، پاڪيزه آهي، برڪت واري آهي. اي اسان جا رب! جيئن توکي پسند هجي ۽ جنهن سان تون راضي ٿي وڃين. قومي ۾، يعني رڪوع مان سر کڻڻ کان پوءِ، اهي ڪلما خاص ڪري نفل نماز ۾ پڙهڻ سنت آهي.", "azkar.057": "(بخاري)", "azkar.058": "اي الله! منهنجي بخشش فرماءِ، مون تي رحم فرماءِ، مون کي هدايت ڏي، مون کي رزق ڏي، مون کي بلند درجو عطا فرماءِ، منهنجو بگڙيل سنواري ڇڏ ۽ مون کي عافيت عطا فرماءِ. ٻنهي سجدن جي وچ ۾ جلسي ۾، خاص ڪري نفل نماز ۾، اهي ڪلما پڙهڻ سنت آهي.", "azkar.059": "(سنن ابوداؤد، ترمذي)", "azkar.060": "آرام جي وقت جا مسنون اذڪار", "azkar.061": "سورة الزمر ۾ ارشادِ الاهي آهي: الله تعاليٰ جانين کي سندن موت وقت وفات ڏئي ٿو ۽ انهن جانين کي به جن کي موت نه آيو آهي، سندن ننڊ وقت. (۴۲)", "azkar.062": "<p class=\"kk-ar\" lang=\"ar\">وَسَبِّحْهُ لَيْلًا طَوِيْلًا</p><p class=\"kk-ur\">سورة الدهر ۾ ارشاد ٿيو: ۽ ڊگهي رات ۾ ان جي تسبيح ڪريو. (۲۶)</p>", "azkar.063": "نبي ڪريم ﷺ فرمايو: دنيا ۾ ڪجهه ماڻهو نرم بسترن تي الله تعاليٰ کي ياد ڪن ٿا، الله تعاليٰ انهن کي اعليٰ جنت ۾ داخل فرمائيندو. (مصنف ابي يوسف). جيڪو شخص بستري تي ليٽي يا ڪنهن مجلس ۾ ويهي ۽ ان ۾ الله تعاليٰ جو ذڪر نه ڪري ته قيامت جي ڏينهن اهو ان لاءِ حسرت هوندو. (ابوداؤد)", "azkar.064": "نوٽ: اسان جا امامِ ربانيؒ سمهڻ وقت سورتون، آيتون، تسبيحات ۽ ماثور دعائون پڙهندا هئا.", "azkar.065": "نبي ڪريم ﷺ سيدنا علي المرتضيٰؓ کي فرمايو ته اي عليؓ! پنج ڪم ڪري سمهندو ڪر:", "azkar.066": "۱. سورة الفاتحه <span class=\"kk-c\">۴ ڀيرا</span>", "azkar.067": "چار ڀيرا پڙهي سمهندو ڪر، اهو چار هزار دينار صدقو ڪرڻ برابر آهي.", "azkar.068": "۲. سورة اخلاص <span class=\"kk-c\">۳ ڀيرا</span>", "azkar.069": "ٽي ڀيرا پڙهي سمهندو ڪر، اهو هڪ ڀيرو قرآن مجيد پڙهڻ برابر آهي.", "azkar.070": "ڏهه ڀيرا پڙهي سمهندو ڪر، ان جو اجر ٻن وڙهندڙن ۾ صلح ڪرائڻ برابر آهي.", "azkar.071": "۴. درود شريف <span class=\"kk-c\">۱۰ ڀيرا</span>", "azkar.072": "ڏهه ڀيرا پڙهي سمهندو ڪر، اهو جنت جي قيمت ادا ڪرڻ برابر آهي.", "azkar.073": "۵. ڪلمهٔ تمجيد <span class=\"kk-c\">۴ ڀيرا</span>", "azkar.074": "چار ڀيرا پڙهي سمهندو ڪر، اهو هڪ حج ڪرڻ برابر آهي.", "azkar.075": "۶. سورة الڪافرون <span class=\"kk-c\">هڪ ڀيرو</span>", "azkar.076": "حضرت نوفلؓ فرمائين ٿا ته نبي ڪريم ﷺ مون کي ارشاد فرمايو: سورة الڪافرون پڙهي سمهندو ڪر، ڇو ته اها شرڪ کان بيزاري آهي.", "azkar.077": "(ابوداؤد)", "azkar.078": "۷. ٽيئي قل شريف <span class=\"kk-c\">۳ ڀيرا</span>", "azkar.079": "ام المؤمنين عائشه صديقهؓ فرمائين ٿيون ته جڏهن نبي ڪريم ﷺ آرام فرمائڻ لاءِ بستري تي تشريف آڻيندا هئا ته ٻئي هٿ ملائي سورة اخلاص ۽ فلق ۽ ناس پڙهي دم ڪندا هئا، ۽ بدنِ اقدس جي جنهن حصي تائين هٿ پهچندا هئا اتي تائين هٿ ڦيريندا هئا، ۽ هٿ ڦيرائڻ جي شروعات مٿي ۽ چهري کان ڪندا هئا، ۽ اهو عمل ٽي ڀيرا ڪندا هئا.", "azkar.080": "(صحيح بخاري)", "azkar.081": "نبي ﷺ فرمايو: جيڪو شخص هي استغفار بستري تي ليٽڻ وقت ٽي ڀيرا پڙهي ٿو ان جا گناهه بخشيا وڃن ٿا، جيتوڻيڪ سمنڊ جي جهاڳ برابر هجن، جيتوڻيڪ وڻن جي پنن برابر هجن، جيتوڻيڪ دڙن جي واريءَ جي ذرن برابر هجن، جيتوڻيڪ دنيا جي ڏينهن برابر هجن.", "azkar.082": "(ترمذي)", "azkar.083": "۹. آيت الڪرسي", "azkar.084": "نبي ﷺ فرمايو: جيڪو شخص سمهڻ وقت آيت الڪرسي پڙهي ته ان جي حفاظت لاءِ هڪ فرشتو مقرر ڪيو وڃي ٿو ۽ صبح تائين شيطان ان جي ويجهو نٿو اچي. (بخاري) جيڪو بستري تي ليٽي اها پڙهندو ته الله تعاليٰ ان جي آسپاس جي ڪيترن ئي گهرن جي حفاظت فرمائي ٿو.", "azkar.085": "۱۰. بسم الله شريف <span class=\"kk-c\">۲۱ ڀيرا</span>", "azkar.086": "نبي ڪريم ﷺ ارشاد فرمايو ته جيڪو شخص سمهڻ کان اڳ ۲۱ ڀيرا تسميه پڙهي ته اهو چوري، شيطاني اثرن ۽ اوچتي موت کان محفوظ رهندو.", "azkar.087": "۱۱. تسبيحِ فاطمه", "azkar.088": "(متفق عليه)", "azkar.089": "۱۲. دعاءِ نوم", "azkar.090": "يا الله! مان تنهنجي ئي نالي سان مران ٿو ۽ تنهنجي ئي نالي سان جيئان ٿو.", "azkar.091": "(متفق عليه)", "azkar.092": "۱۳. سورة البقره جون آخري ٻه آيتون", "azkar.093": "جمعي جي رات ۽ جمعي جي ڏينهن جا مسنون اذڪار", "azkar.094": "نوٽ: اسان جا امامِ رباني مجدد الفِ ثانيؒ گهڻي ڀاڱي نبي ڪريم ﷺ جي بارگاهه ۾ قسمين قسمين درود شريف موڪليندا هئا، خاص ڪري جمعي جي رات ۽ جمعي جي ڏينهن، سومر جي رات ۽ سومر جي ڏينهن. آخري زماني ۾ جمعي جي رات مريدن سان گڏ حلقهٔ ذڪر کان پوءِ هزار ڀيرا درود شريف موڪليندا هئا.", "azkar.095": "۱. جمعي جي رات جو درود شريف <span class=\"kk-c\">هزار ڀيرا</span>", "azkar.096": "۲. جمعي کان پوءِ جو درود شريف <span class=\"kk-c\">هزار ڀيرا</span>", "azkar.097": "شيخ عبدالقادر جيلانيؒ غنية الطالبين ۾ جمعي جي ڏينهن هي درود شريف پڙهڻ جي تلقين فرمائي آهي.", "azkar.098": "۳. عصر جي نماز کان پوءِ جو درود شريف <span class=\"kk-c\">۸۰ ڀيرا</span>", "azkar.099": "سيدنا ابوهريرهؓ کان روايت ٿيل ارشادِ نبوي ﷺ آهي: جنهن جمعي جي ڏينهن عصر جي نماز پڙهي ان ئي جاءِ تي ويٺي ۸۰ ڀيرا هي درودِ پاڪ پڙهيو ته ان جا ۸۰ سالن جا گناهه بخشيا ويندا ۽ ان جي اعمال نامي ۾ ۸۰ سالن جي عبادت جو ثواب لکيو وڃي ٿو.", "azkar.100": "(ديلمي، امام سخاوي)", "azkar.101": "۴. ڪيمياءِ مشائخ", "azkar.102": "شيخ عبدالحق محدث دهلويؒ اڳين پوين گناهن جي مغفرت لاءِ هڪ آزمودو وظيفو «ڪيمياءِ مشائخ» لکيو آهي ته جمعي جي نماز جو سلام ڦيرائڻ کان پوءِ تشهد جي حالت ۾ سورة فاتحه ۽ ٽيئي قل شريف تسميه سميت ست ست ڀيرا پڙهو. حديث شريف ۾ آهي ته انهن سورتن جو پڙهڻ هن جمعي کان ايندڙ جمعي تائين شيطان کان پناهه ڏيندو.", "azkar.103": "(ڪيمياءِ سعادت)", "azkar.104": "نوٽ: امامِ ربانيؒ جمعي جي نماز کان پوءِ سورة فاتحه ۽ ٽيئي قل تسميه سميت ست ست ڀيرا پڙهندا هئا.", "azkar.105": "<p class=\"kk-ar\" lang=\"ar\">فَاِذَا قُضِيَتِ الصَّلٰوةُ فَانْتَشِرُوْا فِي الْاَرْضِ وَابْتَغُوْا مِنْ فَضْلِ اللّٰهِ</p><p class=\"kk-ur\">پوءِ جڏهن نماز پوري ٿي وڃي ته زمين ۾ پکڙجي وڃو ۽ الله جو فضل ڳوليو. (سورة جمعه: ۱۰)</p>", "azkar.106": "حضرت انسؓ فرمائين ٿا: خريد و فروخت ۽ دنيا ڪمائڻ هن آيت جي معنيٰ ناهي، بلڪه علم حاصل ڪرڻ، ڀائرن جي زيارت، بيمارن جي عيادت، جنازي سان گڏ وڃڻ ۽ جيڪي به اهڙا نيڪ ڪم هجن، اهي هن آيت مان مراد آهن. ڇو ته الله تعاليٰ سورة جمعه ۾ اڳتي ارشاد فرمايو آهي:", "azkar.107": "<p class=\"kk-ar\" lang=\"ar\">وَاذْكُرُوا اللّٰهَ كَثِيْرًا لَّعَلَّكُمْ تُفْلِحُوْنَ</p><p class=\"kk-ur\">۽ الله جو ذڪر گهڻو ڪريو ته جيئن توهان ڪامياب ٿيو.</p>", "programs.001": "سالياني پروگرام", "atiyat.001": "عطيا", "atiyat.002": "تحريڪ جي ديني ۽ اصلاحي خدمتن ۾ تعاون ڪرڻ وارن لاءِ — الله تعاليٰ قبول فرمائي.", "rabta.001": "رابطو", "about.001": "ايپ بابت", "kutub.020": "خوفِ خدا ۽ عشقِ مصطفيٰ ﷺ", "kutub.021": "<span>مؤلف:</span> باني ۽ قائد تحريڪ اتباع سنت پاڪستان، پيرِ طريقت، شيرِ مجدد بدرالهديٰ ڪرامت علي رزّاقي عظيمي نقشبندي <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.022": "<span>معاونت:</span> انجنيئر شعيب عالم عظيمي مجددي (ايم اي علومِ اسلاميه)، <span class=\"lat\">HOD</span> اليڪٽريڪل ٽريڊ، گورنمينٽ ٽيڪنيڪل ٽريننگ انسٽيٽيوٽ لوڌران", "kutub.023": "صفحا: <span class=\"lat\">128</span>  • اشاعت: ڊسمبر <span class=\"lat\">2019</span> (ٻيو ايڊيشن)"};
